(window.GIM_TS=window.GIM_TS||{})["Bava Batra.13"]={"from":312,"a":[["\u0003נפל הבית עליו ועל אשתו\u0004 שאין לה ילדים ממנו, ומתו שניהם, ואולם לא ידוע מי מהם מת ראשון. \u0003יורשי הבעל אומרים:\u0004 ה\u0003אשה מתה ראשון\u0004 (ראשונה) \u0003ואחר כך מת הבעל,\u0004 והוא ירש אותה, ולכן הכל שלהם. ואילו \u0003יורשי אשה אומרים:\u0004 ה\u0003בעל מת ראשון ואחר כך מתה\u0004 ה\u0003אשה,\u0004 והיא זכתה בכתובתה, שכן זכותה לקבל כתובתה מנכסי בעלה במקרה שימות לפניה, וכן נכסים שהביאה עמה בנישואיה.","\u0003בית שמאי אומרים: יחלוקו. ובית הלל אומרים:\u0004 \u0003נכסים,\u0004 כלומר, נכסי \"צאן ברזל\", שהביאה האשה עמה בנישואיה, ואחריותם על הבעל, ישארו \u0003בחזקתן. כתובה\u0004 תישאר \u0003בחזקת יורשי הבעל\u0004 שהרי הכתובה היא רכוש הבעל שממנו גובה האשה. \u0003נכסים הנכנסין והיוצאין עמה,\u0004 שהם נכסי מלוג, שהביאה מבית אביה, והם רכושה גם בזמן הנישואין (אף שהבעל אוכל פירותיהם), כיון שהם שלה יהיו \u0003בחזקת יורשי האב,\u0004 כלומר, אבי האשה, שהוא היורשה כשאין לה ילדים."],["שנינו במשנה שבית הלל אומרים שהנכסים בחזקתם, ואנו מבינים שהכוונה היא לסוג נוסף של נכסים, שאינם נכסי מלוג, אלא נכסי צאן ברזל — מה שהביאה האשה מבית אביה, והבעל קיבל על עצמו להחזירם כפי שהיו. ושואלים: \u0003בחזקת מי\u0004 הנכסים הללו? \u0003ר' יוחנן אמר:\u0004 \u0003בחזקת יורשי הבעל,\u0004 שהם באחריותו. \u0003ור' אלעזר אמר: בחזקת יורשי האשה,\u0004 שהרי נכסים אלה מבית האשה באו ושלה הם.","\u0003ור' שמעון בן לקיש משום\u0004 (בשם) \u0003בר קפרא אמר: יחלוקו. וכן תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא\u0004 בברייתות שבידו: \u0003הואיל והללו באין לירש והללו באין לירש,\u0004 ואין ראיה לאחד מהם — \u0003יחלוקו.\u0004","\u0003נפל הבית עליו ועל אמו\u0004 ומתו שניהם, ואולם לא ברור מי מהם מת ראשון. ובאים קרובי האם (מצד משפחת אביה) וטוענים שהבן מת לפני אמו, ולכן הוא לא זכה ברכוש האם, והם יורשיה. וקרובי הבן (מצד אביו) תובעים את רכוש האם בטענה שהיא מתה תחילה ובנה ירש אותה, ורק אחר כך מת. במקרה זה, \u0003אלו ואלו\u0004 (בית שמאי וגם בית הלל, שחלקו עליהם במשנה הקודמת) \u0003מודין שיחלוקו. אמר\u0004 \u0003ר' עקיבא: מודה אני בזו שהנכסים בחזקתן. אמר לו בן עזאי: על חלוקין אנו מצטערין,\u0004 כלומר, לא די שאנו מצטערים על המחלוקת הראשונה, בין בית הלל ובית שמאי, \u0003אלא שבאת לחלק עלינו את השוין\u0004 את הדבר שבו הם מסכימים?!","על מה שאמר ר' עקיבא במשנה שהנכסים בחזקתן, יש לשאול: \u0003בחזקת מי? ר' אילא אמר:\u0004 הכוונה היא \u0003בחזקת יורשי האם. ר' זירא\u0004 מבבל \u0003אמר: בחזקת יורשי הבן.\u0004 מסופר: \u0003כי סליק\u0004 \u0005[כאשר\u0006 \u0005עלה]\u0006 \u0003ר' זירא\u0004 מבבל לארץ ישראל, \u0003קם בשיטתיה\u0004 \u0005[עמד בשיטתו]\u0006 של \u0003ר' אילא,\u0004 כלומר, חזר בו מדבריו וקיבל את שיטת ר' אילא, ואילו בבבל \u0003קם\u0004 \u0005[עמד]\u0006 \u0003רבה\u0004 והחזיק \u0003בשיטתיה\u0004 \u0005[בשיטתו]\u0006 של \u0003ר' זירא. אמר ר' זירא, שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אוירא\u0004 \u0005[שאוירה]\u0006 של \u0003ארץ ישראל מחכים,\u0004 שהרי כשעליתי לארץ ישראל קיבלתי את שיטת ר' אילא שאף הוא היה מארץ ישראל, ואילו רבה שנשאר בבבל מחזיק בשיטתי.","ושואלים: \u0003וטעמא מאי\u0004 \u0005[ומהו הטעם]\u0006 שהנכסים בחזקת יורשי האם? \u0003אמר אביי: הואיל והוחזקה נחלה באותו שבט\u0004 של האם, שהיו הנכסים ברשותה מתחילה, והיא שייכת לאותו שבט, ולכן שוב אין מוציאים מהם לתת לקרובי הבן, שאביו בן משפחה אחרת.","שנינו במשנה ש\u0003אמר לו בן עזאי: על החלוקין אנו מצטערין\u0004 אלא שבאת לחלק עלינו את השווים. על סגנון דבריו של בן עזאי \u0003אמר ר' שמלאי, עדא אמרה\u0004 \u0005[זאת אומרת]:\u0006 \u0003בן עזאי תלמיד חבר\u0004 של \u0003ר' עקיבא הוה\u0004 \u0005[היה],\u0006 \u0003דקאמר ליה\u0004 \u0005[שהוא אומר לו]\u0006 בלשון נוכח \u0003\"שבאת\",\u0004 ולא אמר לו בלשון של כבוד ומורא \"שבא רבינו\" וכיוצא בזה.","\u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]\u0006 הלכה זו: \u0003בן שלוה בנכסי אביו בחיי אביו, ומת\u0004 האב — \u0003בנו מוציא מיד הלקוחות, ו\u0004הלכה \u0003זו היא שקשה בדיני ממונות\u0004 שהסברה בה קשה, אף שברור שהיא הלכה פסוקה. ועל עצם ההלכה תוהים: אם הבן \u0003לוה\u0004 מנכסי האב \u0003מאי מפיק\u0004 \u0005[מה\u0006 יש לו \u0005להוציא]?\u0006 שהרי הוא צריך לשלם ולא לקבל! \u0003ועוד, לקוחות מאי עבידתיה\u0004 \u0005[מה מעשיהם],\u0006 הרי לא נזכרו כאן כלל לקוחות! \u0003אלא אי איתמר\u0004 \u0005[אם נאמר]\u0006 הדבר, \u0003הכי\u0004 \u0005[כך]\u0006"],["\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003בן שמכר בנכסי אביו בחיי אביו, ומת\u0004 הבן, ואחר כך מת אביו — \u0003בנו\u0004 של אותו בן \u0003מוציא\u0004 את הנכסים שמכר אביו \u0003מיד הלקוחות. וזו היא שקשה בדיני ממונות,\u0004 ומה הקושי? \u0003ולימרו ליה\u0004 \u0005[ושיאמרו לו]\u0006 הקונים: \u0003אבוך מזבין ואת מפיק\u0004 \u0005[אביך מוכר ואתה מוציא]?!\u0006","ושואלים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושי]?\u0006 \u0003דלמא מצי אמר\u0004 \u0005[שמא יכול\u0006 הוא \u0005לומר]:\u0006 \u0003מכח אבוה דאבא קאתינא\u0004 \u0005[אביו של אבי אני בא],\u0006 שאני יורש אותו. \u0003תדע\u0004 שכן הוא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תחת אבתיך יהיו בניך תשיתמו לשרים בכל הארץ\"\u0004 (תהלים מה, יז)!","\u0003אלא אי קשיא\u0004 \u0005[אם קשה]\u0006 דבר בדיני ממונות, \u0003הא קשיא\u0004 \u0005[זה\u0006 מה ש\u0005קשה]:\u0006 \u0003בן בכור שמכר חלק בכורה\u0004 שלו \u0003בחיי אביו, ומת בחיי אביו\u0004 — \u0003בנו מוציא\u0004 את החלק הזה \u0003מיד הלקוחות. וזו היא שקשה בדיני ממונות\u0004 שכן \u0003אבוה מזבין, איהו מפיק\u0004 \u0005[אביו מוכר,\u0006 ו\u0005הוא מוציא]?\u0006 \u0003וכי תימא, הכא נמי אמר\u0004 \u0005[ואם תאמר, כאן גם כן\u0006 הוא \u0005אומר]:\u0006 \u0003מכח אבוה דאבא קאתינא\u0004 \u0005[אבי אבא אני בא],\u0006 אם כן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003מכח אבוה דאבא קא אתיא\u0004 \u0005[אבי אבא הוא בא],\u0006 \u0003בחלק בכורה מאי עבידתיה\u0004 \u0005[מה מעשיו]?\u0006","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושי]?\u0006 \u0003דלמא מצי אמר\u0004 \u0005[שמא יכול\u0006 הוא \u0005לומר]:\u0006 \u0003מכח אבוה דאבא קאתינא\u0004 \u0005[מכוח אבי אבא אני בא]\u0006 \u0003ובמקום אב קאימנא\u0004 \u0005[אני עומד]!\u0006","\u0003אלא אי קשיא, הא קשיא\u0004 \u0005[אם קשה, זה\u0006 מה ש\u0005קשה]:\u0006 מי ש\u0003היה יודע לו\u0004 \u0003עדות\u0004 \u0003בשטר,\u0004 כלומר, היה חתום כעד על שטר של חבירו \u0003עד שלא\u0004 (טרם) \u0003נעשה\u0004 אותו עד \u0003גזלן, ונעשה\u0004 לאחר מכן \u0003גזלן\u0004 ואז הוא נפסל לכל עדות — \u0003הוא\u0004 עצמו \u0003אינו מעיד על כתב ידו\u0004 לומר שכתב ידו הוא זה, על מנת לקיים את השטר, שהרי הוא עתה פסול לעדות, \u0003אבל אחרים מעידין\u0004 שזה כתב ידו; והקושי הוא: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003איהו\u0004 \u0005[הוא]\u0006 עצמו \u0003לא מהימן\u0004 \u0005[נאמן],\u0006 אף שהוא יודע בוודאות, \u0003אחריני מהימני\u0004 \u0005[אחרים נאמנים]?!\u0006 \u0003וזו היא שקשה בדיני ממונות.\u0004","ותוהים: \u0003מאי קושיא\u0004 \u0005[מה הקושי\u0006 בזה\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר בהלכה זו, \u0003כגון שהוחזק\u0004 כבר \u0003כתב ידו בבית דין\u0004 לפני שנפסל, ועדות העדים היא רק לאשר שהוחזק בבית דין!","\u0003אלא אי קשיא הא קשיא\u0004 \u0005[אם קשה זה\u0006 מה ש\u0005קשה]:\u0006 \u0003היה יודע לו\u0004 לחבירו \u0003עדות בשטר\u0004 על קרקע מסויימת \u0003עד שלא תפול לו בירושה,\u0004 ואחר כך נפלה לו בירושה, ונעשה נוגע בדבר באותו שטר — \u0003הוא אינו יכול לקיים כתב ידו, אבל אחרים יכולין לקיים כתב ידו.\u0004 ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושי]?\u0006 \u0003דלמא הכא נמי\u0004 \u0005[שמא כאן גם כן]\u0006 מדובר \u0003כגון שהוחזק כתב ידו בבית דין\u0004 כשלא היה נוגע בדבר!","\u0003אלא אי קשיא הא קשיא\u0004 \u0005[אם קשה זה\u0006 מה ש\u0005קשה]:\u0006 \u0003היה יודע לו בעדות\u0004 בשטר \u0003עד שלא נעשה חתנו, ונעשה חתנו\u0004 — \u0003הוא אינו מעיד על כתב ידו,\u0004 לפי שעכשיו הוא פסול להעיד לו, כקרובו, \u0003אבל אחרים מעידין.\u0004 ויש לתמוה: \u0003הוא לא מהימן\u0004 \u0005[נאמן],\u0006 \u0003אחריני מהימני\u0004 \u0005[אחרים נאמנים]?\u0006","\u0003וכי תימא הכא נמי\u0004 \u0005[ואם תאמר\u0006 כי \u0005כאן גם כן]\u0006 מדובר \u0003כגון שהוחזק כתב ידו בבית דין, והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יוסף בר מניומי אמר רב נחמן:\u0004 אחרים מעידים על כתב ידו \u0003אף על פי שלא הוחזק כתב ידו בבית דין!\u0004","ומשיבים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושי\u0006 בדבר\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 ההלכה שאינו יכול להעיד עכשיו לחותנו \u0003גזירת מלך היא דאיהו\u0004 \u0005[שהוא]\u0006 \u0003לא מהימן\u0004 \u0005[נאמן]\u0006 \u0003ואחריני מהימני\u0004 \u0005[ו\u0006אולם \u0005אחרים נאמנים],\u0006 \u0003ולאו\u0004 \u0005[ואין\u0006 זה\u0005]\u0006 \u0003משום\u0004 שחושדים בו שהוא \u0003משקר! דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך],\u0006 \u0003משה ואהרן\u0004 שהם היו פסולים להעיד \u0003לחותנם,\u0004 וכי \u0003משום דלא מהימני\u0004 \u0005[שאינם נאמנים]\u0006 \u0003הוא,\u0004 שחושדים בהם שהם משקרים? \u0003אלא גזירת מלך הוא שלא יעידו להם\u0004 הקרובים זה לזה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003גזירת מלך הוא שלא יעיד על כתב ידו לחותנו!\u0004","\u0003אלא, לעולם\u0004 יש לחזור ולומר \u0003כדאמרינן מעיקרא\u0004 \u0005[כפי שאמרנו מתחילה],\u0006 שהערה זו, \"וזו היא שקשה בדיני ממונות\", נאמרה על ההלכה שמי שמכר נכסי אביו ומת, שבנו מוציא מן הלקוחות. \u0003ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך\u0004 שאין קושי בדבר, שהרי כתוב: \u0003\"תחת אבתיך יהיו בניך\"!\u0004 באמת אין משם ראיה, כי \u0003ההוא\u0004 אותו פסוק \u0003בברכה כתיב\u0004 \u0005[נאמר],\u0006 ואינו בא לקבוע הלכה.","ומקשים: \u0003ומי מצית אמרת\u0004 \u0005[והאם יכול אתה לומר]\u0006 כי \u0003בברכה\u0004 בלבד \u0003כתיב\u0004 \u0005[\u0006הוא \u0005שנאמר],\u0006"],["\u0003אבל לענין דינא\u0004 \u0005[דין]\u0006 \u0003לא?\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נפל הבית עליו ועל אביו,\u0004 או \u0003עליו ועל מורישיו\u0004 האחרים, ומתו כולם, ולא ידוע מי מהם מת קודם, \u0003והיתה עליו\u0004 על הבן \u0003כתובת אשה ובעל חוב, יורשי האב אומרים: הבן מת ראשון\u0004 לפני שמת האב, ואביו ירש אותו, \u0003ואחר כך מת האב,\u0004 ולכן אנו יורשים את כל הנכסים. \u0003ובעל חוב אומר: האב מת ראשון ואחר כך מת הבן,\u0004 והוא ירש את אביו, ואנו יכולים לגבות מרכוש זה.","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ב\u0003\"יורשי האב\"\u0004 — ל\u0003בני\u0004 \u0005[בנים]\u0006 של אותו בן שמת, ו\u0003\"מורישיו\"\u0004 הם \u0003אחי\u0004 \u0005[אחיו]\u0006 של הבן. \u0003ואי סלקא דעתך לא מצי אמר \"מכח אבוה דאבא קאתינא\"\u0004 \u0005[ואם עולה על דעתך\u0006 ש\u0005אין\u0006 הנכד \u0005יכול לומר \"מכוח אבי אבא אני בא\"],\u0006 \u0003דכי כתיב\u0004 \u0005[\u0006לפי \u0005שכאשר נאמר]:\u0006 \u0003\"תחת אבתיך יהיו בניך\"\u0004 — \u0003בברכה\u0004 בלבד \u0003כתיב\u0004 \u0005[נאמר],\u0006 אם כן, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מת הבן ואחר כך מת האב מאי הוי\u0004 \u0005[מה נהיה,\u0006 מה בכך\u0005]\u0006 שהבן מת ראשון ואחר כך האב? \u0003נימא להו\u0004 \u0005[שיאמר להם]\u0006 \u0003בעל חוב\u0004 לבני הבן: את \u0003ירושת אבוהון קא שקילנא\u0004 \u0005[אביהם אני לוקח],\u0006 שהרי לדרך זאת מכוח אביהם הם יורשים!","ודוחים: \u0003לא, יורשי האב\u0004 האמורים כאן הם \u0003אחיו\u0004 של הבן, והם בוודאי יורשים מכוחו של האב. \u0003מורישיו\u0004 האמורים כאן הם \u0003אחי דאבוה\u0004 \u0005[אביו],\u0006 ולפיכך אין להביא מכאן הוכחה שהנכד יורש במישרין את אבי אביו.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 \u0003מרב ששת: בן מהו\u0004 הדין \u0003לענין\u0004 \u0003שיירש את אמו בקבר להנחיל לאחין מן האב?\u0004 כלומר, אם מת הבן ואימו מתה אחריו, האם נאמר שהבן הזה נחשב כזוכה בירושת אימו, הגם שהוא כבר מת וטמון בקבר. וכיון שזכות הירושה מגיעה אליו, הרי אחיו מן האב, למרות שאינם בני אותה אם, יורשים אותו? \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת, תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 בברייתא: \u0003האב שנשבה\u0004 ומת בשבי בתאריך לא ידוע, \u0003ומת בנו במדינה,\u0004 כלומר, לפנינו. \u0003ו\u0004כן במקרה הפוך, \u0003בן שנשבה ומת אביו במדינה,\u0004 ובשני האופנים הללו לא ברור מי מת קודם — \u0003יורשי האב ויורשי הבן יחלוקו.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא כדקתני\u0004 \u0005[אם תאמר כ\u0006לשון \u0005ששנינו],\u0006 הרי אין לדברים משמעות, כי \u0003הי נינהו\u0004 \u0005[מי הם]\u0006 \u0003יורשי האב והי נינהו\u0004 \u0005[ומי הם]\u0006 \u0003יורשי הבן?\u0004 הרי כל יורשי האב הם גם יורשי הבן! \u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר]:\u0006 \u0003אב שנשבה ומת בן בתו במדינה, ו\u0004כן \u0003בן בתו שנשבה ומת אבי אמו במדינה, ולא ידעינן הי מינייהו מית ברישא\u0004 \u0005[ואין אנו יודעים איזה מהם מת בראשונה].\u0006 ואם הסב מת תחילה, הרי ירשו הנכד, והקרובים מצד אביו הם היורשים אותו. אבל אם מת הנכד תחילה ולא ירש את סבו — יורשי הסב מקבלים את כל ירושתו. ועל כך אמרו: \u0003יורשי האב ויורשי הבן יחלוקו.\u0004","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום להלכה שהבן יורש את אמו בקבר, \u0003נהי נמי\u0004 \u0005[גם אם נניח]\u0006 שה\u0003בן מת ברישא\u0004 \u0005[בראשונה],\u0006 מכל מקום יש לומר \u0003לירתיה לאבוה דאמיה בקבריה\u0004 \u0005[שיירש את אבי אמו בקברו]\u0006 \u0003ולירתינהו לאחוה מן אבוה\u0004 \u0005[ושיורישם לאחיו מן האב],\u0006 ונמצא הכל שייך ליורשי הבן! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003אין הבן יורש את אמו בקבר להנחיל לאחין מאב.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר מניומי לאביי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 הוכחה לכך מן המשנה: \u0003נפל הבית עליו ועל אמו\u0004 — \u0003אלו ואלו מודים שיחלוקו; ואם איתא\u0004 \u0005[יש]\u0006 מקום להלכה שהבן יורש את אמו בקבר, \u0003נהי נמי\u0004 \u0005[גם אם אמנם]\u0006 נניח שה\u0003בן מת ברישא\u0004 \u0005[בתחילה],\u0006 \u0003לירתיה לאמיה בקבריה ולירתו אינהו לאחי מאבוה\u0004 \u0005[שיירש את אמו בקבר, ושיירשו הם, אחי אביו]!\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003אין הבן יורש את אמו בקבר להנחיל לאחין מן האב?\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: \u0003וטעמא מאי\u0004 \u0005[מהו טעם\u0006 הדבר\u0005]\u0006 שאינו יורש את אמו בקבר? \u0003אמר אביי: נאמרה\u0004 בכתוב לשון \u0003סיבה\u0004 (הסבת נחלה) \u0003בבן ונאמרה סיבה בבעל\u0004 (ראה לעיל בבא בתרא קיג,א), \u0003מה סיבה האמורה בבעל\u0004 — \u0003אין הבעל יורש את אשתו בקבר\u0004 שלאחר שמת בחייה ודאי אינו יורש אותה במותה להעביר את נחלתה ליורשיו, \u0003אף סיבה האמורה בבן\u0004 — \u0003אין הבן יורש את אמו בקבר להנחיל לאחין מן האב.\u0004","מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 את \u0003נכסי\u0004 \u0005[הנכסים]\u0006 של \u0003בר סיסין מזבנינא\u0004 \u0005[אני מוכר]\u0006 \u0003לך. הואי חדא ארעא דהוה מיקריא\u0004 \u0005[היתה\u0006 חלקת \u0005אדמה אחת שהיתה נקראת]\u0006 \u0003\"דבי\u0004 \u0005[של בית]\u0006 \u0003בר סיסין\", אמר ליה\u0004 \u0005[לו]\u0006 המוכר לקונה: \u0003הא לאו דבי\u0004 \u0005[זו איננה של בית]\u0006 \u0003בר סיסין היא, ו\u0004רק \u0003איקרויי\u0004 \u0005[להיקרא]\u0006 \u0003הוא דמיקריא\u0004 \u0005[שנקראת]\u0006 \u0003\"דבי\u0004 \u0005[של בית]\u0006 \u0003בר סיסין\",\u0004 ולכן אין היא כלולה במכירה.","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 הענין \u0005לפני]\u0006 \u0003רב נחמן, אוקמה בידא\u0004 \u0005[העמיד\u0006 את הקרקע הזו \u0005ביד]\u0006 ה\u0003לוקח. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: דינא הכי\u0004 \u0005[כך\u0006 הוא \u0005הדין]?\u0006 הלא \u0003המוציא מחבירו עליו הראיה,\u0004 ויוכיח הקונה, שהוא התובע, שהדין עמו! ומעירים: \u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003רבא\u0004 על דברי \u0003רבא, ו\u0004מדברי \u0003רב נחמן\u0004 על דברי \u0003רב נחמן\u0004 ממעשה אחר;","\u0003דההוא\u0004 \u0005[ש\u0006אדם \u0005אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003מאי בעית בהאי ביתא\u0004 \u0005[מה רצונך,\u0006 מה אתה עושה \u0005בבית זה]\u0006 שהוא שלי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מינך זבינתה ואכלית\u0004 \u0005[ממך קניתי\u0006 את הבית \u0005ואכלתי,\u0006 נהניתי מפירותיו\u0005]\u0006 \u0003שני\u0004 (שנות) \u0003חזקה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא בשכוני גואי הואי\u0004 \u0005[אני ביישוב הפנימי הייתי\u0006 כל הזמן\u0005],\u0006 במקום רחוק, ולא מכרתי לך בית זה, וגם לא ידעתי כלל שאתה מתגורר בביתי, ואם כן, לא קנית דבר.","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רב נחמן, אמר ליה\u0004 \u0005[לו,\u0006 למחזיק\u0005]:\u0006 \u0003זיל ברור\u0004 \u0005[לך ברר,\u0006 הוכח\u0005]\u0006 את \u0003אכילתך,\u0004 הבא ראיה שבאמת אכלת שלוש שנות חזקה כאשר המוכר היה מצוי במקום, ויכול היה למחות בך ולא עשה כן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: דינא הכי\u0004 \u0005[כך הדין]?\u0006 הלא \u0003המוציא מחבירו עליו הראיה.\u0004 ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבא\u0004 על דברי \u0003רבא, ו\u0004מדברי \u0003רב נחמן\u0004 על דברי \u0003רב נחמן!\u0004 ומתרצים: מדברי \u0003רבא\u0004 על דברי \u0003רבא לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 ב\"נכסי דבי בר סיסין\", ה\u0003מוכר קאי בנכסיה\u0004 \u0005[עומד,\u0006 מחזיק, \u0005בנכסיו],\u0006 והקונה הוא התובע שיתן לו חלקת אדמה נוספת, \u0003התם\u0004 \u0005[שם]\u0006 ה\u0003לוקח קאי בנכסיה\u0004 \u0005[עומד בנכסיו],\u0006 שהרי הוא בפועל גר באותו בית, והתובע הוא הרוצה להוציאו ממנו. וכן מדברי \u0003רב נחמן\u0004 על דברי \u0003רב נחמן לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כיון\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דבי\u0004 \u0005[של בית]\u0006 \u0003בר סיסין\u0004 אני מוכר לך, \u0003ומיקריא\u0004 \u0005[ונקראת]\u0006 האדמה הזו \u0003\"דבי\u0004 \u0005[של בית]\u0006 \u0003בר סיסין\",\u0004 הרי על פני הדברים נראה שהלוקח צודק, ולכן \u0003עליה דידיה רמיא לגלויי דלאו דבי\u0004 \u0005[עליו עצמו,\u0006 על המוכר, \u0005מוטל לגלות שלא של בית]\u0006 \u0003בר סיסין היא. הכא\u0004 \u0005[כאן]\u0006 במקרה של הבית, \u0003לא יהא אלא\u0004 מקרה \u0003דנקיט שטרא\u0004 \u0005[שמחזיק\u0006 בידו \u0005שטר\u0006 מכירה\u0005],\u0006 ואינו טוען לבעלות בגלל החזקה, \u0003מי לא אמרינן ליה\u0004 \u0005[האם אין אנו אומרים לו]:\u0006 \u0003קיים שטרך וקום בנכסי\u0004","","",""],["\u0003גט\u0004 (שטר) \u0003פשוט,\u0004 כלומר, שטר רגיל שהוא פרוש לפנינו במרווח — \u0003עדיו מתוכו,\u0004 שהעדים חותמים באותו צד שנכתב השטר, מתחת נוסח השטר. גט \u0003מקושר\u0004 שכתיבתו נעשית בצורה מיוחדת בקיפולים ובקשרים — \u0003עדיו\u0004 חותמים \u0003מאחוריו.\u0004","שטר \u0003פשוט שכתבו עדיו מאחוריו,\u0004 או שטר \u0003מקושר שכתבו עדיו מתוכו —\u0004 \u0003שניהם פסולין.\u0004 ואילו \u0003ר' חנינא בן גמליאל אומר: מקושר שכתבו עדיו מתוכו —\u0004 \u0003כשר, מפני שיכול לעשותו פשוט\u0004 על ידי שיתיר קשריו ויפתח אותו, ויהא זה שטר פשוט. \u0003רבן שמעון בן גמליאל אומר: הכל כמנהג המדינה.\u0004","ועוד חילוק בין שני סוגי השטרות: \u0003גט פשוט\u0004 — \u0003עדיו בשנים\u0004 ודי בכך, \u0003ומקושר\u0004 — \u0003בשלשה\u0004 לפחות. \u0003פשוט שכתב בו עד אחד\u0004 בלבד, \u0003ומקושר שכתב בו\u0004 רק \u0003שני עדים\u0004 — \u0003שניהם פסולין.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שיש מיני שטרות שונים זה מזה? \u0003אמר ר' חנינא,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"שדות בכסף יקנו וכתוב בספר וחתום והעד עדים\"\u0004 (ירמיהו לב, מד), וכך הוא מסביר: \u0003\"שדות בכסף יקנו וכתוב בספר\"\u0004"],["\u0003זה\u0004 שטר \u0003פשוט\u0004 שהוא כעין ספר, העשוי כמגילה, \u0003\"וחתום\"\u0004 שהוא קשור וצרור — \u0003זה\u0004 שטר \u0003מקושר, \"והעד\"\u0004 — הרי למדנו מכאן \u0003שנים\u0004 עדים, שאין עדות בפחות משנים, \u0003\"עדים\"\u0004 משמעו להוסיף — \u0003שלשה, הא\u0004 \u0005[הרי]\u0006 \u0003כיצד? שנים לפשוט, שלשה למקושר.\u0004","ושואלים: וכיון שהדבר לא נתבאר בכתוב, \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 ואומר שבפשוט צריכים שלושה ובמקושר שנים! ומשיבים: \u0003מתוך שנתרבה\u0004 ונשתנה המקושר על ידי \u0003קשריו,\u0004 מסתבר לומר כי גם \u0003נתרבה בעדיו.\u0004","\u0003רפרם אמר,\u0004 יש ראיה לדבר \u0003מהכא\u0004 \u0005[מכאן\u0006 מכתוב זה\u0005]:\u0006 \u0003\"ואקח את ספר המקנה את החתום המצוה והחקים ואת הגלוי\"\u0004 (ירמיהו לב, יא), \u0003\"ואקח את ספר המקנה\"\u0004 — \u0003זה\u0004 שטר \u0003פשוט, \"את החתום\"\u0004 — \u0003זה מקושר, \"ואת הגלוי\"\u0004 — \u0003זה פשוט שבמקושר,\u0004 כלומר, אותו חלק שבשטר המקושר שהוא פשוט,","\u0003\"המצוה והחקים\"\u0004 — \u0003אלו דברים ש\u0004מבדילים בהלכה \u0003בין פשוט למקושר, הא\u0004 \u0005[הרי]\u0006 \u0003כיצד? זה עדיו שנים וזה עדיו שלשה, זה עדיו מתוכו וזה עדיו מאחוריו.\u0004","ושואלים: \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 שהרי לא נתבאר בכתוב כיצד צריך לעשות בכל אחד משני השטרות הללו! ומשיבים: \u0003מתוך שנתרבה\u0004 המקושר \u0003בקשריו נתרבה בעדיו.\u0004","\u0003רמי בר יחזקאל אמר, מהכא\u0004 \u0005[מכאן]\u0006 יש רמז לדבר: \u0003\"על פי שנים עדים או על פי שלשה עדים יקום דבר\"\u0004 (דברים יט, טו), ויש לשאול: \u0003אם תתקיים עדותן בשנים, למה פרט לך\u0004 הכתוב שהוא גם \u0003בשלשה?\u0004 אלא \u0003לומר לך: שנים\u0004 עדים \u0003לפשוט, שלשה\u0004 עדים \u0003למקושר.\u0004","ושואלים: \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]!\u0006 ומשיבים: \u0003מתוך שנתרבה\u0004 המקושר \u0003בקשריו נתרבה\u0004 גם \u0003בעדיו.\u0004","ומקשים על כולם: \u0003והני להכי הוא דאתו\u0004 \u0005[ואלה\u0006 הפסוקים הללו האם \u0005לכך הוא שבאו]\u0006 ללמד על שטר פשוט ומקושר? והרי \u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מהם \u0003למילתיה\u0004 \u0005[לעניינו]\u0006 המיוחד \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"שדות בכסף יקנו וכתוב בספר וחתום\"\u0004 (ירמיהו לב, מד) — \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 לעשות קנין שדות בשטר, כדי שתהיה ראיה קיימת לדבר. ומה שנאמר \u0003\"ואקח את ספר המקנה\"\u0004 — \u0003הכי הוה\u0004 \u0005[כך היה]\u0006 \u0003מעשה.\u0004 ומה שנאמר: \u0003\"על פי שנים עדים או על פי שלשה עדים\"\u0004 — הרי זה \u0003להקיש\u0004 (להשוות) \u0003שלשה\u0004 עדים \u0003לשנים,\u0004 ו\u0003ב\u0004ענין \u0003פלוגתא\u0004 \u0005[המחלוקת]\u0006 של \u0003ר' עקיבא ורבנן\u0004 \u0005[וחכמים]\u0006 בענין זה (במסכת מכות דף ה, ב), מה בדיוק מלמדנו ההיקש!","\u0003אלא,\u0004 יש לדחות את כל מה שאמרנו, ולומר כך: שטר \u0003מקושר\u0004 הוא באמת \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 שחכמים הם שתיקנו אותו, \u0003וקראי אסמכתא בעלמא\u0004 \u0005[והמקראות\u0006 שהביאו הם \u0005סמך,\u0006 רמז \u0005בלבד].\u0006","ושואלים: \u0003וטעמא מאי תקינו רבנן\u0004 \u0005[ומה טעם תיקנו חכמים]\u0006 גט \u0003מקושר?\u0004 ומסבירים: \u0003אתרא דכהני הוו\u0004 \u0005[מקום של כהנים היה],\u0006 \u0003והוו קפדי טובא ומגרשי נשייהו\u0004 \u0005[והיו כועסים הרבה ומגרשים\u0006 את \u0005נשיהם],\u0006 וכהן הרי אסור בגרושה, ואף בגרושתו שלו. ואם יתחרט הכהן, לאחר שישכך כעסו, על שגירש את אשתו — שוב אין לו תקנה. \u0003ועבדי רבנן תקנתא\u0004 \u0005[ו\u0006לפיכך \u0005עשו חכמים תקנה]\u0006 לכתוב סוג שטר מסובך כזה, \u0003אדהכי והכי מיתבא דעתייהו\u0004 \u0005[שבין כך וכך תתיישב דעתם\u0006 של הכהנים\u0005]\u0006 ולא יגרשו.","ושואלים: \u0003התינח\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 ב\u0003גיטין\u0004 שיש טעם לעשותם מקושרים, אבל \u0003שטרות\u0004 סתם \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: באמת בשטרות אחרים לא היה הדבר נחוץ, אלא \u0003כדי שלא תחלק בין גיטין לשטרות\u0004 אחרים.","ושואלים: \u0003היכן עדים חותמין\u0004 בשטר מקושר? \u0003רב הונא אמר: בין קשר לקשר, ורב ירמיה בר אבא אמר: אחורי הכתב\u0004 של השטר, מצדו האחורי, \u0003ו\u0004יש להקפיד שתהיה החתימה בדיוק \u0003כנגד הכתב מבחוץ.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר חמא לרב חסדא: ל\u0004דעת \u0003רב הונא\u0004 ש\u0003אמר בין קשר לקשר, קא סלקא דעתין\u0004 \u0005[עלה על דעתנו]\u0006 לומר שהכוונה \u0003בין קשר לקשר מגואי\u0004 \u0005[מבפנים],\u0006 כלומר, בתוך החלק המקופל. ויש להקשות: \u0003והא\u0004 \u0005[והרי]\u0006 מעשה היה ב\u0003ההוא\u0004 \u0005[באותו]\u0006 שטר \u0003מקושר דקאתא לקמיה\u0004 \u0005[שבא לפני]\u0006 \u0003רבי, ואמר רבי\u0004 בתמיהה: וכי \u0003אין\u0004 כתוב ה\u0003זמן בזה? אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון ברבי לרבי: שמא בין קשריו מובלע,\u0004 כלומר, שמא בתוך הקשרים הללו כתבו את הזמן? \u0003פלייה וחזייה\u0004 \u0005[פתח אותו וראה אותו],\u0006 שאכן היה הזמן כתוב שם. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי רב הונא שחותמים בין קשר לקשר: \u0003\"אין זמן בזה ואין עדים בזה\" מיבעיא ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שהרי אף חתימות העדים מצויות בתוך הקשרים!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שחותם \u0003בין קשר לקשר מגואי\u0004 \u0005[מבפנים]\u0006 ואין החתימה נראית? \u0003לא,\u0004 הכוונה היא: \u0003בין קשר לקשר מאבראי\u0004 \u0005[מבחוץ].\u0006","ושואלים: אם העדים חותמים מבחוץ (ולא בסוף נוסח השטר, כמו בשטר פשוט), והשטר כתוב מן הצד האחר — \u0003וניחוש דלמא זייף וכתב מאי דבעי\u0004 \u0005[ונחשוש שמא\u0006 לאחר שיחתמו העדים, \u0005יזייף\u0006 האיש \u0005ויכתוב מה ש\u0006הוא \u0005רוצה]\u0006 בתוכו של השטר, \u0003וחתימי סהדי\u0004 \u0005[והעדים\u0006 כבר \u0005חתומים]\u0006 על השטר!","ומשיבים: \u0003דכתיב ביה\u0004 \u0005[שכתוב בו]\u0006 בסוף כתיבת השטר נוסח האישור: \u0003\"שריר וקיים\",\u0004 ורק לאחר שכתוב הנוסח כך, אז חותמים העדים.","ומקשים: \u0003וניחוש דלמא\u0004 \u0005[ונחשוש שמא]\u0006 לאחר שנכתב \"שריר וקיים\" וחתמו העדים \u0003כתב מאי דבעי\u0004 \u0005[מה ש\u0006הוא \u0005רוצה],\u0006 \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003כתב \"שריר וקיים\" אחרינא\u0004 \u0005[אחר]\u0006 על התוספת שזייף והוסיף! ומשיבים: \u0003חד\u0004 \u0005[אחד]\u0006 \u0003\"שריר וקיים\" כתבינן\u0004 \u0005[אנו כותבים]\u0006 בשטר, \u0003תרי\u0004 \u0005[שני]\u0006 \u0003\"שריר וקיים\" לא כתבינן\u0004 \u0005[כותבים אנו],\u0006 ואם נכתב בו פעמיים — הרי החלק האחרון זיוף הוא.","ומקשים: \u0003וליחוש דלמא מחיק ליה\u0004 \u0005[ונחשוש שמא מחק]\u0006 את \u0003\"שריר וקיים\"\u0004 הראשון, ו\u0003כתב מאי דבעי\u0004 \u0005[מה ש\u0006הוא \u0005רוצה],\u0006 \u0003והדר\u0004 \u0005[ו\u0006אחר כך \u0005חזר]\u0006 ו\u0003כתב \"שריר וקיים\"!\u0004 ומשיבים: שטר כזה, שנמחק וחזרו וכתבו בו — אין סומכים עליו כלל, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' יוחנן:\u0004 אם היתה \u0003תלויה,\u0004 כלומר, מלה שטעה הסופר ודילג עליה, וכתב אותה בין השורות, אם היא \u0003מקויימת,\u0004 שבסוף השטר כותב שהוסיפו בשטר מלה מסויימת — הרי זו \u0003כשרה,\u0004"],["\u0003מחק\u0004 (מקום מחוק בשטר), ופעמים נכתב דבר במקום המחק — הרי הוא \u0003פסול, ואף על פי ש\u0004השטר \u0003מקוים\u0004 אחר כך, שכתוב בו שמחקו וכתבו במקום המחק.","\u0003ולא אמרו מחק פסול\u0004 — \u0003אלא במקום\u0004 שהיה צריך כרגיל להיכתב בו \u0003\"שריר וקיים\", ו\u0004כן כשהיה גודלו של המחק לפחות \u0003כשיעור \"שריר וקיים\".\u0004","ועוד שאל רמי בר חמא את רב חסדא: \u0003ול\u0004דעת \u0003ר' ירמיה בר אבא\u0004 ש\u0003אמר:\u0004 חותמים \u0003אחורי הכתב וכנגד הכתב מבחוץ,\u0004 ולשיטתו אין כותבים בסוף שטר כזה \"שריר וקיים\", \u0003ליחוש דלמא כתיב מגואי מאי דבעי\u0004 \u0005[נחשוש שמא\u0006 מוסיף ו\u0005כותב מבפנים מה ש\u0006הוא \u0005רוצה]\u0006 \u0003ו\u0004הוא \u0003מחתים סהדי יתירי מאבראי\u0004 \u0005[עדים נוספים מבחוץ],\u0006 \u0003ואמר\u0004 \u0005[ואומר]\u0006 להם, לשואלים אותו מדוע רבים כל כך העדים: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לרבות בעדים הוא דעבדי\u0004 \u0005[שעשיתי]\u0006 כדי לפרסם ולחזק את הדבר יותר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003עדים כסדרן חתימי\u0004 \u0005[\u0006הם \u0005חתומים]\u0006 מלמעלה למטה? לא, \u0003עדים ממטה למעלה חתימי\u0004 \u0005[חתומים]\u0006 מסוף השטר לתחילתו, ולא ניתן להוסיף חתימה קודם לכן, לפי שאז מתגלה הזיוף.","ושואלים: \u0003וליחוש דלמא מתרמיא ריעותיה\u0004 \u0005[ו\u0006עדיין \u0005נחשוש שמא מצוי\u0006 דבר ש\u0005מרע לו]\u0006 \u0003בשיטה\u0004 (שורה) \u0003אחרונה, וגייז ליה\u0004 \u0005[וחותך אותה]\u0006 את ה\u0003שיטה\u0004 ה\u0003אחרונה, וגייז ליה\u0004 \u0005[וחותך]\u0006 את שם העד החתום מאחוריה, כגון \u0003ראובן בהדיה\u0004 \u0005[יחד איתה],\u0006 \u0003ו\u0004עדיין \u0003מתכשר\u0004 \u0005[\u0006הגט \u0005כשר]\u0006 \u0003ב\u0004מה שכתוב בו המשך החתימה: \u0003\"בן יעקב עד\", דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אם כתוב רק \u0003\"בן איש פלוני עד\"\u0004 ולא כתוב שם העד עצמו \u0003כשר!\u0004","ומשיבים: גט מקושר כשר רק במקרה \u0003דכתב\u0004 \u0005[שכתוב\u0006 בו בצורה הבאה\u0005]:\u0006 \u0003\"ראובן בן\" בחד דרא\u0004 \u0005[בשורה אחת]\u0006 כנגד השורה האחרונה, \u0003\"ויעקב עד\" עלוויה\u0004 \u0005[עליה]\u0006 כנגד השורה שלפניה.","ואומרים: והלא גם במקרה כזה, \u0003וליחוש דלמא גייז ליה\u0004 \u0005[ונחשוש שמא חתך אותו]\u0006 את השורה האחרונה בשטר, וחותך עמו מה שכתוב בעבר השני \u0003\"ראובן בן\", ומתכשר\u0004 \u0005[ו\u0006מכל מקום \u0005מוכשר\u0006 הגט\u0005]\u0006 \u0003ב\u0004מה שכתוב רק \u0003\"יעקב עד\", דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אם כתוב רק \u0003\"איש פלוני עד\",\u0004 בלי שם אביו — \u0003כשר!\u0004","ומשיבים: מדובר במקרה ש\u0003לא כתיב\u0004 \u0005[כתוב]\u0006 \u0003\"עד\".\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 מדובר ש\u0003כתב \"עד\",\u0004 אלא \u0003דידעינן בה דהא חתימות ידא\u0004 \u0005[שיודעים אנו בו שחתימת יד זו]\u0006"],["\u0003לאו\u0004 \u0005[לא]\u0006 של \u0003יעקב הוא.\u0004","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 יבואו להכשיר שטר כזה, שיאמרו: \u0003בשמיה דאבוה\u0004 \u0005[בשם אביו]\u0006 \u0003חתם\u0004 הבן, משום כבודו של אביו! ומשיבים: לא יבואו לומר כן, לפי ש\u0003לא שביק איניש שמיה דידיה וחתים בשמיה דאבוה\u0004 \u0005[אין אדם מניח\u0006 את \u0005שמו שלו וחותם בשם אביו].\u0006","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 יאמרו: \u0003סימנא בעלמא\u0004 \u0005[סימן בלבד]\u0006 \u0003הוא דשוויה\u0004 \u0005[שעשה אותו],\u0006 שיהיה זה כעין חותמת, שעושה את שם אביו לסימן, ולא שכותב את שם אביו כחתימתו שלו! \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רב\u0004 במקום חתימה \u0003צייר כוורא\u0004 \u0005[היה מצייר דג],\u0006 \u0003ר' חנינא צייר חרותא\u0004 \u0005[היה מצייר ענף דקל],\u0006 \u0003רב חסדא\u0004 היה מצייר צורת האות \u0003סמ\"ך, רב הושעיא\u0004 — \u0003עי\"ן, רבא בר רב הונא\u0004 — \u0003מכותא\u0004 \u0005[תורן ספינה]!\u0006 ומשיבים: \u0003לא חציף אינש לשוויה לשמיה דאבוה סימנא\u0004 \u0005[אין אדם חצוף לעשות את שם אביו סימן].\u0006","\u0003מר זוטרא אמר: למה לך כולי האי\u0004 \u0005[כל זה,\u0006 כל התירוצים הללו\u0005]?\u0006 לדעת ר' ירמיה בר אבא, \u0003כל\u0004 שטר \u0003מקושר שאין\u0004 חתימות \u0003עדיו כלין\u0004 (נגמרים) \u0003בשיטה\u0004 (שורה) \u0003אחת\u0004 — \u0003פסול.\u0004 וכיון שכולם נכתבים יחד — אינו יכול להוסיף עד, ולא לחתוך שורה מן השטר.","\u0003אמר רב יצחק בר יוסף אמר ר' יוחנן: כל המחקין כולן,\u0004 כלומר, כל מקום שנמחק דבר בשטר, וחזרו וכתבו עליו, \u0003צריך שיכתוב\u0004 בסוף השטר שיש מחקים \u0003\"ודין קיומיהון\"\u0004 \u0005[\"וזה קיומם\"].\u0006 \u0003וצריך שיחזור\u0004 ויכתוב דברים \u0003מענינו של שטר,\u0004 ממה שכבר נכתב בו, \u0003בשיטה אחרונה\u0004 שלפני חתימת העדים, ולא יוסיף בה דברים מעבר למה שכבר נכתב בשטר. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמרו דבר זה?"],["\u0003אמר רב עמרם: לפי שאין למדין משיטה אחרונה,\u0004 כלומר, אין מתחשבים במה שכתוב בשורה האחרונה בגלל חשש לזיוף.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב עמרם: מנא\u0004 \u0005[מנין]\u0006 \u0003לך הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרחיק את העדים שני שיטין\u0004 (שורות) \u0003מן הכתב\u0004 — הרי זה \u0003פסול,\u0004 אבל אם הרחיק \u0003שיטה אחת\u0004 — \u0003כשר;\u0004 ויש לשאול:","\u0003מאי שנא\u0004 \u0005[במה שונה,\u0006 מדוע\u0005]\u0006 אם הרחיק \u0003שני שיטין\u0004 הריהו פסול? —שכן יש לחשוש \u0003דלמא מזייף וכתב\u0004 \u0005[שמא יזייף ויכתוב]\u0006 בעל השטר בתוך שתי השורות הללו דבר מה, ואולם \u0003שיטה אחת נמי מזייף וכתב\u0004 \u0005[גם כן\u0006 יכול \u0005לזייף ולכתוב],\u0006 ומדוע אין חוששים לכך ולפסול את השטר? \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003אין למדין משיטה אחרונה,\u0004 ולכן אין עוד מקום לחשוש שמא הוסיף וזייף בשורה זו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא."],["\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אם היה בין השטר וחתימת העדים רוחב \u0003שיטה\u0004 (שורה) \u0003ומחצה, מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: \u0003הרחיק את העדים שני שיטין\u0004 — \u0003פסול,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם המרחק הוא \u0003שיטה ומחצה\u0004 — \u0003כשר.\u0004","ודוחים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של ברייתא זו: אם הרחיק רק \u0003שיטה אחת\u0004 — \u0003כשר,\u0004 ונדייק מכאן: מרחק \u0003שיטה אחת הוא\u0004 ש\u0003כשר, הא\u0004 \u0005[הרי]\u0006 מרחק \u0003שיטה ומחצה\u0004 — \u0003פסול! אלא מהא ליכא למשמע מינה\u0004 \u0005[מזו אין לשמוע ממנה\u0006 פתרון לבעיה\u0005]\u0006 בדרך דיוק.","ואם כן, שואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על הבעיה? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרחיק את העדים שני שיטין מן הכתב\u0004 — \u0003פסול, פחות מכאן\u0004 — \u0003כשר,\u0004 ומכאן הוכחה שמרחק שיטה ומחצה כשר, שהרי זה פחות משנים.","ועוד נאמר באותה ברייתא: \u0003היו ארבעה וחמשה עדים חתומין על השטר, ונמצא אחד מהן קרוב\u0004 לאחד הצדדים, והרי הוא פסול לעדות לו, \u0003או\u0004 שהוא \u0003פסול\u0004 לעדות מצד עצמו — \u0003תתקיים עדות בשאר,\u0004 שדי בשנים לעדות, ואין האחרים פוסלים אותה.","ומעירים: הלכה אחרונה זו \u0003מסייע ליה\u0004 \u0005[מסייעת לו]\u0006 \u0003ל\u0004שיטת \u0003חזקיה,\u0004 ש\u0003אמר חזקיה:\u0004 \u0003מלאהו\u0004 את הרווח של שתי השורות שבין הכתב לחתימות העדים \u0003ב\u0004חתימות של \u0003קרובים\u0004 — \u0003כשר\u0004 השטר, למרות שאם לא היו חותמים שם הקרובים היה השטר פסול.","\u0003ואל תתמה\u0004 על הבחנה זו, \u0003שהרי\u0004 כך גם מצאנו בהלכה אחרת: \u0003אויר סוכה,\u0004 חלק מן הסוכה שאינו מכוסה בסכך — \u0003פוסל\u0004 את הסוכה \u0003בשלשה\u0004 טפחים, ואילו אם היה שם \u0003סכך פסול\u0004 — \u0003פוסל\u0004 רק \u0003בארבעה\u0004 טפחים. ומכאן ראיה שדבר פסול פוסל פחות מאשר פוסל העדר.","וחוזרים לדון בענין הראשון. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003שני שיטין שאמרו\u0004"],["האם הכוונה היא \u0003הן ואוירן,\u0004 כלומר, שיעור השורות והחלל שביניהן, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003הן ולא אוירן?\u0004","\u0003אמר רב נחמן בר יצחק: מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003הן ואוירן, דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003הן ולא אוירן, שיטה\u0004 (שורה) \u0003אחת בלא אוירה למאי חזיא\u0004 \u0005[למה\u0006 היא \u0005ראויה]?\u0006 הרי אין שם מקום לכתוב דבר! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003הן ואוירן,\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003ר' שבתי אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה:\u0004 אותן \u0003שני שיטין שאמרו\u0004 שאין להרחיק בין השטר לעדים — הן נמדדות \u0003בכתב ידי עדים\u0004 לפי גודל הכתב שלהם, \u0003ולא כתב ידי סופר,\u0004 שהוא כרגיל קטן יותר מכתב ידי העדים, מאחר שהוא מיומן בכתיבה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ש\u0003כל המזייף, לאו לגבי ספרא אזיל\u0004 \u0005[לא אצל הסופר\u0006 הוא \u0005הולך]\u0006 \u0003ומזייף,\u0004 ולכן אין לחשוש אלא שבעל השטר, שאינו מיומן כל כך בכתיבה, הוא יזייף את השטר בעצמו.","\u0003וכמה\u0004 שיעורן של שורות אלה? \u0003אמר רב יצחק בן אלעזר: כגון\u0004 שיכול לכתוב בהן את שתי המילים \u0003\"לך לך\" זה על גבי זה.\u0004 ואומרים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005הוא סבור]\u0006 שהרווח שאסור להשאיר הוא של \u0003שני שיטין\u0004 של כתב \u0003וארבעה אוירין,\u0004 אויר אחד מעל השורה הראשונה — לגגה של ה־ל', אויר נוסף מתחת לשורה השניה — לרגלה של ה־ך', ושני אוירים בין השורות למקרה שה־ל' תבוא מתחת ל־ך'.","\u0003רב חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא אמר: כגון למ\"ד מלמעלה וכ\"ף מלמטה. אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005הוא סבור]:\u0006 \u0003שני שיטין ושלשה אוירין,\u0004 אחד לגג ה־ל' שבעליונה, אחד לרגל ה־ך' שבתחתונה, ואחד בין השורות. וגם אם מזדמן לו ל' מתחת ל־כ' סופית — הוא מזיז אותה מעט, כדי שלא יגעו זו בזו.","\u0003ר' אבהו אמר: כגון\u0004 שיכתוב את המלים: \u0003\"ברוך בן לוי\" בשיטה אחת;\u0004 ואומרים \u0003קא סבר\u0004 \u0005[סבור הוא]:\u0006 \u0003שיטה אחת ושני אוירין,\u0004 אחד מלמטה (בשביל \"ברוך\") ואחד מלמעלה (בשביל \"לוי\").","\u0003אמר רב: לא שנו\u0004 שלא יעשה רווח של שתי שורות \u0003אלא בין עדים לכתב\u0004 השטר, \u0003אבל בין עדים לאשרתא,\u0004 כלומר, ההנפק — הקיום, שמאשרים בית הדין את חתימת ידי העדים — \u0003אפילו טובא נמי\u0004 \u0005[הרבה\u0006 רווח \u0005גם כן]\u0006 \u0003כשר.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003בין עדים לכתב\u0004 שלא ירחיק? — \u0003דלמא מזייף וכתב מאי דבעי וחתימי סהדי\u0004 \u0005[שמא יזייף ויכתוב מה שירצה והעדים חתומים\u0006 על כך\u0005],\u0006 אם כן \u0003בין עדים לאשרתא\u0004 \u0005[לקיום]\u0006 \u0003נמי מזייף וכתב מאי דבעי וחתימי סהדי\u0004 \u0005[גם כן\u0006 יש לחשוש שמא \u0005יזייף ויכתוב מה שירצה והעדים חתומים]!\u0006","ומשיבים: \u0003דמטייט ליה\u0004 \u0005[שממלא בסימני דיו]\u0006 את כל הרווח הזה, כך שאי אפשר יהיה לכתוב עליו. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003בין עדים לשטר נמי מטייט ליה\u0004 \u0005[גם כן יעשה סימנים\u0006 כאלה\u0005]\u0006 ומדוע אוסרים להרחיק?","ומשיבים: כשרואים שטר כזה, \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003סהדי אטיוטא\u0004 \u0005[העדים על הטיוטא,\u0006 השרטוט הזה\u0005]\u0006 \u0003הוא דחתימי\u0004 \u0005[שחתומים],\u0006 ולא על גוף השטר, ויפסלו אותו. ומקשים: אם כן, \u0003בין עדים לאשרתא נמי אמרי\u0004 \u0005[גם כן יאמרו]:\u0006 \u0003בי דינא אטיוטא\u0004 \u0005[בית הדין על הטיוט]\u0006 \u0003הוא דחתימי\u0004 \u0005[שחתומים],\u0006 ולא קיימו את השטר! ומשיבים: \u0003בי דינא אטיוטא לא חתימי\u0004 \u0005[בית דין על טיוט אינם חותמים],\u0006 שעדים עשויים לחתום על דבר של מה בכך, אבל בית דין אינו יושב לחתום על דבר כזה.","ושואלים עוד: אם יש רווח גדול בין העדים לאשרתא, הרי גם אם הוא מטוייט בדיו, \u0003וליחוש דלמא גייז ליה לעילא\u0004 \u0005[ונחשוש שמא יחתוך את\u0006 כל החלק \u0005העליון\u0006 של השטר\u0005],\u0006 \u0003ומחיק ליה לטיוטא\u0004 \u0005[וימחוק את הטיוט]\u0006 \u0003וכתב מאי דבעי ומחתים סהדי\u0004 \u0005[ויכתוב מה שירצה\u0006 במקום המחוק \u0005ויחתים\u0006 על כך \u0005עדים],\u0006 \u0003ו\u0004יוכל להשתמש בו, עם האשרתא הכתובה כבר קודם לכן מתחתיו, שהרי \u0003אמר רב: שטר הבא הוא ועדיו על המחק\u0004 שהכל נכתב על גבי קלף או נייר מחוק — הרי זה \u0003כשר!\u0004"],["\u0003הניחא\u0004 \u0005[זה\u0006 אמנם \u0005נוח]\u0006 \u0003ל\u0004שיטת \u0003רב כהנא דמתני לה משמיה\u0004 \u0005[ששונה\u0006 את ההלכה \u0005הזו משמו]\u0006 של \u0003שמואל\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 שאז אין סתירה בדברי רב, ויש לומר שרב פוסל שטר כזה. \u0003אלא לרב טביומי דמתני לה משמיה\u0004 \u0005[ששונה אותה משמו]\u0006 של \u0003רב,\u0004 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 רב כי \u0003כל\u0004 שטר \u0003כי האי גוונא\u0004 \u0005[כגון זה],\u0006 שהוא ועדיו על המחק, \u0003אין מקיימין אותו מן האשרתא\u0004 \u0005[הקיום]\u0006 \u0003שבו, אלא\u0004 דווקא \u0003מן העדים שבו,\u0004 וכשיבדקו — יגלו שהשטר מזוייף. עד כאן דנו בשיטתו של רב, שהוא מתיר להשאיר רווח אפילו מרובה בין העדים לקיום.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 להיפך: \u0003לא שנו\u0004 רווח של שתי שורות פוסל, \u0003אלא\u0004 כשהוא \u0003בין העדים לכתב, אבל\u0004 אם הוא \u0003בין עדים לאשרתא\u0004 \u0005[לקיום]\u0006 — \u0003אפילו\u0004 רווח של \u0003שיטה אחת פסול.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 הרווח ש\u0003בין עדים לאשרתא\u0004 \u0005[לקיום],\u0006 שחושש ר' יוחנן אפילו לרווח של שורה אחת? — שיש לחשוש \u0003דלמא גייז לעילאי\u0004 \u0005[שמא יחתוך את\u0006 החלק \u0005העליון]\u0006 \u0003וכתב\u0004 \u0005[ויכתוב]\u0006 שטר חדש \u0003הוא ועדיו\u0004 \u0003בשיטה\u0004 (שורה) \u0003אחת, וקסבר\u0004 \u0005[והוא,\u0006 ר' יוחנן, \u0005סבור]\u0006 ש\u0003שטר הבא הוא ועדיו בשיטה אחת\u0004 — \u0003כשר;\u0004","\u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם יש רווח של שורה אחת \u0003בין עדים לכתב נמי\u0004 \u0005[גם כן],\u0006 יש לחשוש \u0003דלמא גייז ליה לעילאי\u0004 \u0005[שמא יחתוך את\u0006 החלק \u0005העליון]\u0006 \u0003וכתב מאי דבעי וחתימי סהדי\u0004 \u0005[ויכתוב מה שירצה, והעדים חתומים]\u0006 מתחת השורה שכתב, ונמצא שיש בידו שטר שקוצר החתום על ידי עדים! ומשיבים: \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003שטר הבא\u0004 לפנינו כאשר \u0003הוא\u0004 השטר \u0003בשיטה אחת ועדיו בשיטה אחרת\u0004 — \u0003פסול.\u0004","ושואלים עוד: \u0003וליחוש דלמא\u0004 \u0005[ונחשוש שמא]\u0006 לאחר שיחתוך את השטר מלמעלה \u0003כתב\u0004 \u0005[יכתוב]\u0006 שטר חדש \u0003הוא ועדיו בשיטה אחת,\u0004 כלומר, באותה שורה ריקה. \u0003ו\u0004כדי להסביר מדוע יש עדים נוספים בשורה האחרת \u0003אמר\u0004 \u0005[יאמר]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לרבות בעדים הוא דעבדי\u0004 \u0005[שעשיתי],\u0006 שהוספתי עוד עדים כדי לפרסם את הדבר!","ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ר' יוחנן ש\u0003כל\u0004 שטר \u0003כי האי גוונא\u0004 \u0005[כגון זה],\u0006 שהוא ועדיו בשורה אחת, ובשורה שמתחתיו חתומים עדים נוספים — \u0003אין מקיימין אותו מן העדים שלמטה\u0004 (שמא הם חתמו על שטר אחר שנחתך), \u0003אלא מן העדים שלמעלה,\u0004 שסמוכים לכתב, וכך יגלו שהוא מזוייף.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה זו שהזכרנו, \u0003אמר רב: שטר הבא הוא ועדיו על המחק\u0004 — \u0003כשר.\u0004"],["\u0003ואם תאמר:\u0004 יכול הוא לזייפו, אם הוא \u0003מוחק וחוזר ומוחק,\u0004 כלומר, שמוחק את השטר שנכתב תחילה על המחק (אבל לא את חתימות העדים), ואז יכתוב בשטר על המקום שמחק מה שירצה, ועדיין יהא שטר שנכתב הוא ועדיו על המחק! יש להשיב: \u0003אינו דומה נמחק פעם אחת לנמחק שתי פעמים\u0004 וניכר שהשטר עצמו כתוב על נייר שנמחק פעמיים, בעוד שהעדים חתומים על נייר שנמחק פעם אחת.","ושואלים: \u0003וליחוש דלמא שדי דיותא\u0004 \u0005[ונחשוש שמא\u0006 יקח שטר מחוק, \u0005ישליך דיו]\u0006 רק על \u0003מקום\u0004 חתימת \u0003עדים מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003ומחיק ליה\u0004 \u0005[וימחוק אותו,\u0006 את הדיו\u0005],\u0006 והעדים חותמים עכשיו על נייר שנמחק פעמיים, \u0003דכי הדר מחיק ליה להאי\u0004 \u0005[שכאשר יחזור וימחוק את זה],\u0006 את נוסח השטר עצמו, ויכתוב שם כרצונו, \u0003הוה ליה אידי ואידי\u0004 \u0005[יהיה לו זה וזה]\u0006 גם השטר המזוייף וגם חתימת העדים, כתובים על נייר ש\u0003נמחק שתי פעמים,\u0004 ואז כבר אי אפשר יהיה להבחין!","\u0003אמר אביי, קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003רב\u0004 ש\u0003אין העדים חותמין על המחק אלא אם כן נמחק בפניהם,\u0004 ואם יראו שמוחק סתם דיו — יחשדו בדבר ולא יחתמו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב, שמכשיר שטר כשהוא ועדיו על המחק, ממה ששנינו בברייתא: היה השטר כתוב \u0003הוא על הנייר\u0004 הנקי, החדש, \u0003ועדיו על המחק\u0004 — \u0003כשר,\u0004 שהרי חתימת העדים ניתנת לקיום; ויש לשאול: אם שטר שנכתב הוא ועדיו על המחק כשר, \u0003וניחוש דלמא מחיק ליה וכתיב מאי דבעי\u0004 \u0005[ונחשוש שמא ימחוק אותו,\u0006 את השטר הכתוב על הנייר \u0005ויכתוב מה שירצה]\u0006 על מקום המחק, \u0003והוי ליה\u0004 \u0005[ויהיה]\u0006 בידו שטר \u0003הוא ועדיו על המחק!\u0004","ומשיבים: שטר כזה כשר דווקא במקרה \u0003דכתבי הכי\u0004 \u0005[שכותבים כך]:\u0006 \u0003\"אנחנא סהדי חתמנא על מחקא ושטרא כתב על ניירא\"\u0004 \u0005[אנו העדים חתמנו על המחק והשטר כתוב על נייר].\u0006","ושואלים: \u0003דכתבי היכא\u0004 \u0005[שכותבים\u0006 דבר זה \u0005היכן]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כותבים אותו \u0003מלתחת\u0004 \u0005[למטה]\u0006 מחתימתם — יש לחשוש שמא \u0003גייז ליה\u0004 \u0005[יחתוך אותו,\u0006 את נוסח זה\u0005]\u0006 ולא ישאר ממנו, \u0003אי עילאי\u0004 \u0005[אם למעלה]\u0006 מחתימתם — \u0003מחיק ליה\u0004 \u0005[ימחוק אותו]\u0006 יחד עם כל השטר! ומשיבים: \u0003דכתבי בין סהדא לסהדא\u0004 \u0005[שכותבים בין עד לעד].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא, ששנינו: היה השטר \u0003הוא על המחק ועדיו על הנייר\u0004 — \u0003פסול,\u0004 שמא מחק את השטר שעדים חתומים עליו, וזייף אותו; ויש לשאול \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פסול? הכא נמי נכתבו הכי\u0004 \u0005[כאן גם כן יכתבו כך]:\u0006 \u0003\"אנחנא סהדי חתמנא על ניירא ושטרא על מחקא\"\u0004 \u0005[אנו העדים חתמנו על הנייר והשטר על המחק]!\u0006","\u0003השתא נמי מאי אמרת\u0004 \u0005[עכשיו גם כן מה אתה אומר]?\u0006 — שאין בכך להועיל, משום שהוא \u0003מוחק\u0004 ושוב \u0003חוזר ומוחק,\u0004 וכותב על המחק דבר חדש שלא חתמו עליו העדים — \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרת\u0004 \u0003:\u0004 \u0003אינו דומה נמחק פעם אחת לנמחק שתי פעמים!\u0004 ומשיבים: \u0003הני מילי היכא דחתימי סהדי אמחקא\u0004 \u0005[דברים אלה,\u0006 שניתן להבחין בין מחיקה אחת ושתיים, אמורים \u0005כאשר העדים\u0006 עצמם \u0005חתומים על מחק]\u0006 ואז אפשר להשוות את המחקים, אבל \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003ל\u0004\u0003א חתימי סהדי אמחקא\u0004 \u0005[חתומים העדים על המחק]\u0006 \u0003אלא אניירא\u0004 \u0005[על נייר]\u0006 — \u0003לא ידיע\u0004 \u0005[נודע]\u0006 ולא ניכר בנייר אם נמחק פעם אחת או שתי פעמים, ולכן פוסלת הברייתא שטר כזה.","ומקשים: והרי עדיין ניתן לבדוק את הדבר, \u0003וליתי מגילתא אחריתי ולמחוק ולידמי\u0004 \u0005[ושיביא מגילה,\u0006 נייר \u0005אחר, ושימחק\u0006 אותו, \u0005ושידמה\u0006 אותו\u0005]\u0006 לשטר, ויראה אם נמחק פעם או פעמיים! ומשיבים: \u0003לא דמי מחקא דהא מגילתא למחקא דהא מגילתא\u0004 \u0005[אינו דומה מחק של מגילה זו למחק של מגילה זו],\u0006 ואי אפשר ללמוד מנייר לנייר.","ומקשים: ועדיין אפשר לבדוק את הדבר באותו שטר עצמו, וכיצד? \u0003ולקבלה לחתימות ידא דסהדי בבי דינא, ולמחוק ולידמי\u0004 \u0005[ושיקבל את חתימת ידי העדים בבית דין,\u0006 ויאשר אותה, \u0005ו\u0006אז \u0005ימחקו\u0006 את החתימות \u0005וידמו]\u0006 את המחק של מקום העדים למחק של השטר, ויראו אם נמחק פעם או יותר! \u0003אמר רב הושעיא: אינו דומה נמחק בן יומו לנמחק בן שני ימים,\u0004 ויכולים לטעות בכך.","ושואלים: \u0003ולישהייה\u0004 \u0005[ושישהה אותו]\u0006 את השטר בבית הדין, ואז אפשר יהיה לדמות! \u0003אמר ר' ירמיה: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לבית דין טועין\u0004 שלא ידקדקו כל כך בבדיקת המחיקה בשטר.","שנינו במשנה ש\u0003ר' חנינא בן גמליאל אומר: מקושר\u0004 שכתבו עדיו מתוכו — כשר, משום שיכול לפושטו ולעשותו פשוט. \u0003השיב רבי\u0004 והקשה \u0003לדברי ר' חנינא בן גמליאל:\u0004"],["\u0003והלא אינו דומה זמנו של זה לזמנו של זה!\u0004 שהרי כלל בידינו שבשטר \u0003פשוט,\u0004 מלך ש\u0003מלך\u0004 \u0003שנה\u0004 — \u0003מונין לו שנה,\u0004 וכותבים בשטר שנעשה בשנה ראשונה של מלך זה, מלך \u0003שתים\u0004 (שתי שנים) — \u0003מונין לו שתים.\u0004 ואילו בשטר \u0003מקושר,\u0004 אם \u0003מלך שנה\u0004 — \u0003מונין לו שתים, שתים\u0004 — \u0003מונין לו שלש;\u0004 ומסבירים את דברי רב:","\u0003וזימנין דיזיף מיניה זוזי\u0004 \u0005[ופעמים שילווה ממנו כספים]\u0006 \u0003ב\u0004שטר \u0003מקושר, ומיתרמי ליה זוזי ביני ביני ופרע ליה\u0004 \u0005[ומזדמנים לו\u0006 ללווה \u0005כספים בינתיים ו\u0006הוא \u0005פורע לו\u0006 למלוה\u0005],\u0006 \u0003ואמר ליה\u0004 \u0005[ואומר לו]\u0006 למלוה: \u0003הב\u0004 \u0005[תן,\u0006 החזר\u0005]\u0006 \u0003לי שטראי\u0004 \u0005[\u0006את \u0005שטרי],\u0006 \u0003ואמר ליה\u0004 \u0005[והוא,\u0006 המלוה, \u0005אומר לו]:\u0006 \u0003אירכס\u0004 \u0005[אבד]\u0006 \u0003לי,\u0004 ובאמת לא אבד, \u0003וכתב ליה תברא\u0004 \u0005[וכותב לו שובר],\u0006 קבלה, שנפרעה הלוואה זו.","\u0003וכי מטי זמניה\u0004 \u0005[וכאשר מגיע זמנו]\u0006 של השטר המקושר לפי התאריך הכתוב בו, \u0003משוי ליה\u0004 \u0005[עושה אותו]\u0006 שטר \u0003פשוט, ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני השתא דיזפת מינאי\u0004 \u0005[אלה\u0006 הם כספים \u0005שעכשיו לווית ממני],\u0006 כלומר, זו היא הלוואה אחרת, שאינה ההלוואה הקודמת שיש עליה שובר. שהרי התאריך שכתוב בשטר מקושר — מאוחר בשנה לתאריך שבשטר פשוט, ונמצא הלווה משלם פעמיים!","ומעירים: ומה ישיב לכך ר' חנינא בן גמליאל? ומשיבים: \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 \u0005:\u0006 \u0003אין כותבין שובר,\u0004 ואין הלווה פורע חוב זה עד שיחזיר המלוה את השטר.","אגב שהובאו דבריו של רבי, שואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 היה \u0003בקי רבי ב\u0004דיני שטר \u0003מקושר? והא ההוא\u0004 \u0005[והרי\u0006 מעשה ב\u0005אותו]\u0006 שטר \u0003מקושר דאתא לקמיה\u0004 \u0005[שבא לפני]\u0006 \u0003רבי, ואמר רבי: שטר מאוחר זה! ואמר לו זונין לרבי: כך מנהגה של אומה זו\u0004 שהשטר נכתב בה, \u0003מלך\u0004 המלך \u0003שנה\u0004 — \u0003מונין לו שתים, שתים\u0004 — \u0003מונין לו שלש\u0004 נמצא שרבי עצמו לא ידע הלכה זו במקושר!","ומשיבים: \u0003בתר\u0004 \u0005[אחר]\u0006 ש\u0003שמעה\u0004 את ההלכה הזו \u0003מזונין, סברה\u0004 \u0005[קיבל אותה],\u0006 וכשהקשה על ר' חנינא בן גמליאל, על סמך הלכה זו ששמע הקשה.","מסופר, \u0003ההוא שטרא דהוה כתב ביה\u0004 \u0005[שטר אחד שהיה כתוב בו]\u0006 \u0003\"בשנת פלוני ארכן\",\u0004 שנכתב בשנה שפלוני היה ממונה על המדינה. \u0003אמר ר' חנינא: יבדק אימתי עמד ארכן בארכנותיה\u0004 \u0005[השר בשררותו]\u0006 שהוא השנה בה נכתב השטר.","ומקשים: \u0003ודלמא דאריך מלכותיה\u0004 \u0005[ושמא\u0006 היה זה הכוונה בביטוי \"ארכן\", לפלוני \u0005שארוכה מלכותו]\u0006 ששימש יותר משנה אחת בתפקיד זה, ואם כן היתה ההלוואה לא בשנה שעלה בה לשלטון, אלא לאחר מכן! \u0003אמר רב הושעיא: כך מנהגה של אומה זו,\u0004 בכתיבה בשטרות, \u0003שנה ראשונה קורין\u0004 (קוראים) \u0003לו \"ארכן\"\u0004 סתם, \u0003שניה\u0004 — \u0003קורין לו דיגון\u0004 (שתיים).","ושואלים: \u0003ודלמא עבורי עברוהו והדר אוקמוהו\u0004 \u0005[ושמא העבירו אותו\u0006 מתפקידו \u0005וחזרו והעמידו אותו]\u0006 לאחר זמן, והשטר נכתב בשנה הראשונה למינויו בשנית! \u0003אמר ר' ירמיה: ההוא\u0004 \u0005[אותו]\u0006 שהעבירו אותו והחזירו אותו, אין קוראים לו \"ארכן\" סתם בשנתו הראשונה, אלא \u0003\"ארכן דיגון\" קראו ליה\u0004 \u0005[קוראים לו].\u0006 אגב שהזכרנו את המילה \"דיגון\" מביאים הלכה שבה מוזכרת מלה זו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם אמר: \u0003\"הריני נזיר הינא\"\u0004 \u0003סומכוס אמר:\u0004 \u0003\"הינא\"\u0004 — כוונתו בלשון יוונית \u0003אחת,\u0004 וכוונתו היתה שנזר נזירות אחת, שסתמה שלושים יום. \u0003\"דיגון\"\u0004 — \u0003שתים,\u0004 כוונתו לשתי נזירויות, שהן שישים יום. \u0003\"טריגון\"\u0004 — \u0003שלש, \"טטריגון\"\u0004 — \u0003ארבע, \"פנטיגון\"\u0004 — \u0003חמש.\u0004","ועוד הלכה בה נזכרות מלים אלה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בית\u0004 שהיה \u0003עגול,\u0004 או שהיה \u0003דיגון\u0004 (בעל שתי זויות, כגון שעשוי כקשת סגורה), או \u0003טריגון\u0004 (משולש), או \u0003פנטיגון\u0004 (בעל חמש צלעות) — \u0003אינו מטמא בנגעים\u0004 בצרעת הבתים. \u0003טטריגון\u0004 (מרובע) — \u0003מטמא בנגעים.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שדווקא בית בעל ארבעה קירות מטמא בנגעים? — \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003למעלה\u0004 הכתוב \u0003אומר \"קיר\" \"קירת\"\u0004 (ויקרא יד, לז) הרי \u0003שתים,\u0004 וגם \u0003למטה\u0004 (ויקרא יד, לט) \u0003אומר \"קיר\" \"קירת\"\u0004 — הרי \u0003שתים,\u0004 אם כן ביחד \u0003הרי כאן ארבע,\u0004 ולכן אומרים שדווקא כשיש ארבעה קירות מיטמא הבית בנגעים.","מסופר, \u0003ההוא\u0004 \u0005[אותו]\u0006 שטר \u0003מקושר דאתא לקמיה\u0004 \u0005[שבא לפני]\u0006 \u0003רבי, ואמר רבי\u0004 בתמיהה: \u0003אין זמן\u0004 כתוב \u0003ב\u0004שטר \u0003זה? אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון בר\u0004 \u0005[בנו]\u0006 של \u0003רבי לרבי: שמא בין קשריו מובלע\u0004 הזמן? \u0003פלייה וחזייה\u0004 \u0005[פתח אותו\u0006 את קשרי הגט \u0005וראה\u0006 את הזמן\u0005].\u0006 \u0003הדר חזא ביה רבי בבישות\u0004 \u0005[חזר והסתכל בו רבי ב\u0006עין \u0005רעה]\u0006 שחשב שהוא עצמו כתב את השטר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' שמעון בנו: \u0003לאו אנא כתבתיה\u0004 \u0005[לא אני כתבתי אותו],\u0006 \u0003ר' יהודה חייטא כתביה\u0004 \u0005[החייט כתב אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי לבנו: \u0003כלך\u0004 \u0005[לך]\u0006 \u0003מלשון הרע הזה,\u0004 שלא היית צריך לספר מי כתב אותו, די היה שתאמר שלא אתה כתבת אותו.","ובדומה לזה מסופר: \u0003זימנין הוה יתיב קמיה\u0004 \u0005[פעם היה יושב לפניו\u0006 לפני רבי\u0005]\u0006 ר' שמעון בנו, \u0003וקא פסיק סידרא\u0004 \u0005[והיה קורא פרשיות]\u0006 \u0003בספר תהלים, אמר רבי: כמה מיושר כתב זה\u0004 של הספר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' שמעון: \u0003לאו אנא כתבתיה\u0004 \u0005[לא אני כתבתי אותו],\u0006 \u0003יהודה חייטא כתביה\u0004 \u0005[החייט כתב אותו].\u0006 \u0003אמר ליה: כלך\u0004 \u0005[לך]\u0006 \u0003מלשון הרע הזה.\u0004","ותוהים: \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 שהיה פגם בשטר, \u0003איכא\u0004 \u0005[יש בכך]\u0006 \u0003לשון הרע, אלא הכא\u0004 \u0005[כאן]\u0006 ששיבח את הכתב, \u0003מאי\u0004 \u0005[מה]\u0006 \u0003לשון הרע איכא\u0004 \u0005[יש כאן]?\u0006 ומשיבים: \u0003משום\u0004 דבריו של \u0003רב דימי, דתני\u0004 \u0005[ששנה]\u0006 \u0003רב דימי אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב ספרא: לעולם אל יספר אדם בטובתו של חבירו, שמתוך טובתו בא לידי רעתו\u0004 ונמצא גורם ללשון הרע.","על סמך דברים אלה וכיוצא בהם, \u0003אמר רב עמרם אמר רב: שלש עבירות אין אדם ניצול מהן בכל יום,\u0004 ואלו הם: \u0003הרהור עבירה\u0004 של זנות, \u0003ועיון תפלה\u0004 שאינו מעיין בתפילתו כראוי, \u0003ולשון הרע.\u0004 ותוהים: \u0003לשון הרע סלקא\u0004 \u0003דעתך\u0004 \u0005[עולה על דעתך]?\u0006 וכי כל אדם חוטא בלשון הרע בכל יום?"],["\u0003אלא,\u0004 הכוונה אינה ללשון הרע ממש, אלא ל\u0003אבק לשון הרע,\u0004 כלומר, דבר היכול להתפרש כלשון הרע.","ובדומה לכך \u0003אמר רב יהודה אמר רב: רוב\u0004 בני אדם נכשלים \u0003בגזל, ומיעוט\u0004 מהם נכשלים \u0003בעריות, והכל\u0004 נכשלים \u0003בלשון הרע.\u0004 ותוהים: \u0003בלשון הרע סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 וכי כל האנשים מדברים לשון הרע?! \u0003אלא,\u0004 הכוונה היא ל\u0003אבק לשון הרע,\u0004 ומזה קשה מאד להינצל.","שנינו במשנה ש\u0003רבן שמעון בן גמליאל אומר: הכל כמנהג המדינה.\u0004 ושואלים: \u0003ו\u0004כי ה\u0003תנא קמא לית ליה\u0004 \u0005[הראשון אין לו,\u0006 אינו מקבל את הדעה\u0005]\u0006 שהולכים אחר \u0003מנהג מדינה?\u0004 ועל מה בא רבן שמעון לחלוק?","\u0003אמר רב אשי,\u0004 כך יש להבין את הדברים: \u0003באתרא דנהיגי\u0004 \u0005[במקום שנוהגים]\u0006 לעשות שטר \u0003פשוט, ואמר ליה\u0004 \u0005[לו]\u0006 לסופר: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003לי פשוט, ואזל עבד ליה\u0004 \u0005[והלך\u0006 ו\u0005עשה לו]\u0006 שטר \u0003מקושר\u0004 — הרי זו \u0003קפידא\u0004 \u0005[הקפדה],\u0006 ולא מילא את השליחות שלו, לדעת כולם. וכן גם להיפך, אם \u0003נהיגי\u0004 \u0005[נוהגים\u0006 לעשות\u0005]\u0006 \u0003מקושר, ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003לי מקושר, ואזל עבד ליה\u0004 \u0005[והלך\u0006 ו\u0005עשה לו]\u0006 שטר \u0003פשוט\u0004 — הרי זו \u0003קפידא\u0004 \u0005[הקפדה].\u0006","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003באתרא דנהיגי\u0004 \u0005[במקום שנוהגים]\u0006 גם \u0003בפשוט ו\u0004גם ב\u0003מקושר, ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003לי פשוט, ואזל עבד ליה\u0004 \u0005[והלך\u0006 ו\u0005עשה לו]\u0006 שטר \u0003מקושר, מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003קפידא\u0004 \u0005[הקפדה\u0006 היא\u0005],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003מראה מקום הוא לו,\u0004 כלומר, נותן לו כעין עצה טובה כיצד יעשה, אבל אינו מקפיד אם משנים מדבריו.","אגב זה \u0003אמר אביי: רבן שמעון בן גמליאל ור' שמעון ור' אלעזר, כולהו סבירא להו\u0004 \u0005[כולם סבורים\u0006 סברה דומה\u0005]\u0006 כל אחד בענין אחר, שלא תמיד אדם מקפיד שיתקיימו דבריו כדיוקם, אלא ש\u0003מראה מקום הוא לו\u0004 אומר את הדברים כהמלצה, ואינו מקפיד אם אינה מתקיימת כלשונה. ובאלו הלכות אמרו חכמים אלה את שיטתם זו?","\u0003רבן שמעון בן גמליאל\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 שכאשר שהוא אומר איזה סוג של שטר לעשות, אינו אומר זאת אלא בגדר עצה טובה ולא יותר. \u0003ר' שמעון\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 שהאדם שמקדש אשה בדבר אחד ונמצא דבר אחר, כגון שקידשה בדינר של זהב ונמצא שהוא של כסף, וכן להיפך. או שמקדש אותה על מנת שהוא עשיר ונמצא שהוא עני, ולהיפך — בטלו הקידושין.","\u0003ר' שמעון אומר: אם הטעה לשבח\u0004 שלפי התנאי היה זה דבר פחות, ובפועל היה זה משובח ממנו — \u0003הרי זו מקודשת\u0004 מתוך הנחה שאם אין בדבר הפסד — אין אדם מקפיד בדבר","\u0003. ר' אלעזר\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה שאמרה\u0004 לשליח: \u0003\"התקבל לי\u0004 (קבל עבורי) מבעלי את \u0003גיטי\u0004 ב\u0003מקום פלוני\",\u0004 \u0003וקיבלו לה מ\u0004בעלה ב\u0003מקום אחר\u0004 — הרי זה \u0003פסול, ור' אלעזר מכשיר.\u0004 ולפי זה: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 סתם משנה, \u0005סבור]:\u0006 \u0003קפידא\u0004 \u0005[הקפדה\u0006 היא\u0005],\u0006 שעמדה על כך שיתקבל הגט דווקא במקום מסויים, \u0003ומר סבר\u0004 \u0005[וחכם זה סבר]:\u0006 \u0003מראה מקום הוא לו.\u0004","שנינו במשנה ששטר \u0003פשוט שכתוב בו\u0004 רק \u0003עד אחד,\u0004 ומקושר שכתובים בו רק שני עדים — פסולים. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ענין זה ש\u0003מקושר שכתוב בו שני עדים פסול\u0004 — \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 לאומרו, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ובעלמא\u0004 \u0005[ובכלל]\u0006 שטר שיש בו שני עדים \u0003כשר\u0004 — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במקושר יהא \u0003כשר,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהוא \u0003פסול. אלא\u0004 שטר \u0003פשוט שכתוב בו עד אחד\u0004 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שהוא פסול!","\u0003אמר אביי: לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא לפסול שטר כזה, \u0003אפילו\u0004 במקרה שהיה \u0003עד אחד בכתב\u0004 בשטר עצמו, \u0003ועד אחד בפה,\u0004 שמעיד על גוף המעשה.","ומעירים: \u0003אמימר אכשר\u0004 \u0005[הכשיר]\u0006 שטר שהיה בו \u0003עד אחד בכתב ועד אחד על פה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: והא\u0004 \u0005[וזו]\u0006 שאמר \u0003אביי\u0004 בענין פסול שטרות, שלמד מן המשנה לפסול שטר כזה, \u0003מאי\u0004 \u0005[מה]\u0006 אתה אומר על כך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שמיע\u0004 \u0003לי\u0004 \u0005[שמעתי]\u0006 דבר זה, שזו היתה לשון נקיה, \u0003כלומר, לא סבירא לי\u0004 \u0005[איני סבור\u0006 כך\u0005]\u0006.","ושואלים: \u0003אלא\u0004 אם דוחים את דברי אביי, אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006"],["\u0003מתניתין\u0004 \u0005[משנתנו]:\u0006 מדוע צריך היה לומר שעד אחד פסול בשטר פשוט?","ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 ש\u0003שנים במקושר\u0004 דינם \u0003כעד אחד בפשוט; מה התם\u0004 \u0005[שם]\u0006 בעד אחד בשטר פשוט הרי זה \u0003פסולא דאורייתא\u0004 \u0005[פסול שמן התורה],\u0006 \u0003אף הכא נמי פסולא דאורייתא\u0004 \u0005[כאן גם כן,\u0006 בשני עדים במקושר הרי זה \u0005פסול מן התורה].\u0006","ומוסיף אמימר: \u0003תדע\u0004 שכך הוא כדברי, שהרי \u0003שלחו מתם חברייא\u0004 \u0005[משם,\u0006 מארץ ישראל, \u0005בני החבורה]\u0006 \u0003לר' ירמיה:\u0004","\u0003עד אחד בכתב ועד אחד על פה, מהו\u0004 הדין לענין \u0003שיצטרפו?\u0004 ומוסיפים דבר זה נראה קשור למחלוקת בברייתא בענין עדות, שם נאמר ששני עדים שלא ראו את העדות יחד — אינם מצטרפים להעיד, ור' יהושע בן קרחה מתיר.","ומעתה \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של \u0003ר' יהושע בן קרחה,\u0004 סתם משנה, \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, שלשיטתו \u0003אפילו שנים\u0004 שמעידים כל אחד מהם \u0003בכתב, ו\u0004כן \u0003שנים על פה לא מצטרפי\u0004 \u0005[מצטרפים]\u0006 אם לא ראו כאחד, למרות שהם מעידים על אותו חוב עצמו. \u0003אלא כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 \u0003ר' יהושע בן קרחה,\u0004 והשאלה היא כך: האם לדעתו \u0003שנים בכתב ו\u0004כן \u0003שנים על פה הוא דמצטרפי\u0004 \u0005[שמצטרפים],\u0006 \u0003אבל עד אחד בכתב ואחד על פה לא מצרפינן\u0004 \u0005[אין אנו מצרפים],\u0006 שהרי שני סוגים של עדות הם. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006","\u0003שלח להו\u0004 \u0005[להם]\u0006 בתשובה: \u0003אני איני כדיי\u0004 (כדאי, ראוי) \u0003ששלחתם לי, אלא כך דעת תלמידכם נוטה\u0004 — \u0003שיצטרפו.\u0004 ומשמע אם כן, שר' ירמיה סבור כאמימר בענין זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לאמימר: \u0003אנן הכי מתנינן לה\u0004 \u0005[אנו כך שונים אותה]\u0006 את השמועה הזו באופן אחר, ש\u0003שלחו ליה חברייא\u0004 \u0005[לו בני החבורה]\u0006 \u0003לר' ירמיה: שנים שהעידו, אחד בבית דין זה ואחד בבית דין זה, מהו שיבואו בית דין אצל בית דין, ויצטרפו\u0004 בתי הדין ויקבלו אותם כעדות אחת? גם דבר זה תלוי קשור למחלוקת תנאים בברייתא בענין עדות. שאם עד מעיד ביום אחד ועד שני מעיד ביום אחר באותו בית דין — לדעת סתם משנה אין העדויות מצטרפות, ואילו ר' נתן אומר שמצטרפות.","ומעתה \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של \u0003ר' נתן,\u0004 שהוא חולק עליו, \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 שהרי \u0003אפילו בחד בית דינא נמי לא מצטרפי\u0004 \u0005[בבית דין אחד גם כן אינם מצטרפים]\u0006 אם אין העדויות נאמרות כאחת, \u0003אלא כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 — הרי זה \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 \u0003ר' נתן;\u0004 האם נאמר לשיטתו כי \u0003בחד בי דינא\u0004 \u0005[בבית דין אחד]\u0006 \u0003הוא דמצטרפי\u0004 \u0005[שמצטרפים],\u0006 \u0003אבל בתרי בי דינא לא מצטרפי\u0004 \u0005[בשני בתי דין אינם מצטרפים],\u0006 \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006","\u0003ושלח להו\u0004 \u0005[להם]\u0006 ר' ירמיה: \u0003אני איני כדיי שאתם שלחתם לי, אלא כך דעת תלמידכם נוטה\u0004 — \u0003שיצטרפו.\u0004","\u0003מר בר חייא אמר, הכי\u0004 \u0005[כך]\u0006 \u0003שלחו ליה\u0004 \u0005[לו],\u0006 כלומר, בנוסח אחר: \u0003שנים שהעידו בבית דין זה וחזרו והעידו בבית דין זה, מהו שיבוא אחד מכל בית דין ויצטרפו\u0004 להיות דיינים בדין זה?","\u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 \u0003ר' נתן לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003עדים מצרפינן\u0004 \u0005[אנו מצרפים],\u0006 \u0003דייני מיבעיא\u0004 \u0005[דיינים נצרכה\u0006 לומר\u0005]\u0006 שהם מצטרפים? \u0003אלא כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — הרי זה \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של \u0003ר' נתן,\u0004 האם לומר כי לשיטתו \u0003עדים הוא דלא מצרפינן\u0004 \u0005[שאין אנו מצרפים],\u0006 \u0003אבל דייני מצרפינן\u0004 \u0005[דיינים אנו\u0006 כן \u0005מצרפים],\u0006 \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006","\u0003שלח להו\u0004 \u0005[להם]:\u0006 \u0003אני איני כדיי שאתם שלחתם לי, אלא כך דעת תלמידכם נוטה\u0004 — \u0003שיצטרפו.\u0004","\u0003רבינא אמר\u0004 נוסח אחר, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003שלחו ליה\u0004 \u0005[לו]:\u0006 \u0003שלשה שישבו\u0004 בבית דין \u0003לקיים את השטר, ומת אחד מהן\u0004 לפני שחתמו, האם \u0003צריכי למכתב\u0004 \u0005[צריכים לכתוב]\u0006 \u0003\"במותב תלתא הוינא וחד ליתוהי\"\u0004 \u0005[במושב שלושה היינו ואחד איננו],\u0006 \u0003או לא?\u0004","\u0003שלח להו\u0004 \u0005[להם]:\u0006 \u0003אני איני כדיי שאתם שלחתם לי, אלא כך דעת תלמידכם נוטה, שצריכין למכתב\u0004 \u0005[לכתוב]:\u0006 \u0003\"במותב תלתא הוינא וחד ליתוהי\"\u0004 \u0005[במושב שלושה היינו ואחד איננו].\u0006","ומעירים: \u0003ועל דא\u0004 \u0005[ובגלל\u0006 תשובה \u0005זו],\u0006 שנאמרה בלשון ענווה, \u0003עיילוהו\u0004 \u0005[הכניסו]\u0006 חכמים את \u0003ר' ירמיה\u0004 שוב \u0003בבי מדרשא\u0004 \u0005[לבית המדרש]\u0006 אחר שהוציאוהו משם משום ששאל שאלות שהיו נראות כקינטור.","\u0003כתוב בו\u0004 בשטר מילוה שהחוב הוא: \u0003\"זוזין מאה דאינון\u0004 \u0005[שהם]\u0006 \u0003סלעין עשרין\",\u0004 וכיון שכל סלע הוא בן ארבעה זוזים (דינרים) הרי זו סתירה בין ההתחלה שכתוב בה מאה זוזים, ובין ההמשך שכתוב בו עשרים סלעים (שהם רק שמונים זוז) \u0003אין לו\u0004 למלווה לגבות בחובו \u0003אלא עשרין\u0004 סלעים, שמונים זוז. אם כתוב שם \u0003\"זוזין מאה דאינון תלתין סלעין\"\u0004 \u0005[שהם שלושים סלעים],\u0006 ושלושים סלעים הריהם מאה ועשרים זוז — \u0003אין לו אלא מנה\u0004 (מאה זוזים).","אם היה כתוב בשטר \u0003\"כסף זוזין דאינון\"\u0004 \u0005[שהם],\u0006 \u0003ונמחק\u0004 הסכום שהיה כתוב שם — \u0003אין פחות משתים\u0004 משני זוזים, שהרי נאמר בו לשון רבים. וכן אם היה כתוב \u0003\"כסף סלעין דאינון\"\u0004 \u0005[שהם],\u0006 \u0003ונמחק\u0004 הסכום — \u0003אין פחות משתים\u0004 משני סלעים. היה כתוב בשטר \u0003\"דרכונות דאינון\u0004 \u0005[שהם]\u0006 \u0003\",\u0004 \u0003ונמחק\u0004 — \u0003אין פחות משתים\u0004 משתי דרכונות (מטבע זהב).","\u0003כתוב בו\u0004 בשטר \u0003מלמעלה מנה ומלמטה מאתים,\u0004 או שהיה כתוב בו \u0003מלמעלה מאתים ומלמטה מנה\u0004 — \u0003הכל הולך אחר התחתון\u0004 שהוא המחייב לענין זה. \u0003אם כן, למה כותבין את העליון?\u0004 לומר \u0003שאם תמחק אות אחת מן התחתון\u0004 ולא יהיה ברור מה כתוב בו — \u0003ילמד מן העליון\u0004 ולכן כותבים פעמיים.","ועוד בהלכות אלה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אמר \"כסף\"\u0004 ולא אמר כמה — \u0003אין פחות מדינר כסף.\u0004 אם אמר \u0003\"כסף דינרין\"\u0004 או \u0003\"דינרין כסף\"\u0004 — \u0003אין פחות משני דינרין כסף.\u0004 אם אמר לשון \u0003\"כסף בדינרין\"\u0004 — \u0003אין פחות מבשני דינרין\u0004 של \u0003דהב\u0004 \u0005[זהב]\u0006 שמשלם אותם במטבעות \u0003כסף.\u0004","ודנים בברייתא: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"כסף\"\u0004 — \u0003אין פחות מדינר כסף.\u0004 ושואלים: \u0003ואימא נסכא\u0004 \u0005[ואמור\u0006 שהכוונה היא ל\u0005חתיכה\u0006 קטנה של \u0005כסף]\u0006 ולא למטבע! \u0003אמר ר' אלעזר:\u0004 ש\u0003כתוב ביה\u0004 \u0005[בו]\u0006 בשטר \u0003\"מטבע\".\u0004 ושואלים: \u0003ואימא פריטי\u0004 \u0005[ואמור\u0006 שהכוונה היא \u0005פרוטות\u0006 של כסף\u0005]\u0006 ולא דינרים! \u0003אמר רב פפא:\u0004 מדובר כאן \u0003באתרא\u0004 \u0005[במקום]\u0006 ש\u0003לא סגי פריטי דכספא\u0004 \u0005[מצויות פרוטות כסף].\u0006","ומביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: אם כתב \u0003\"דהב\"\u0004 \u0005[זהב]\u0006 — \u0003אין פחות מדינר דהב\u0004 \u0005[זהב].\u0006 אם היה כתוב \u0003\"דהב דינרין\"\u0004 או \u0003\"דינרין דהב\"\u0004 — \u0003אין פחות משני דינרין דהב\u0004 \u0005[זהב].\u0006 אם היה כתוב \u0003\"דהב בדינרין\"\u0004 — \u0003אין פחות מבשני דינרין כסף,\u0004 ומשלם במטבע \u0003דהב\u0004 \u0005[זהב].\u0006 ודנים בפרטי ברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"דהב\"\u0004 \u0003—\u0004 \u0003אין פחות מדינר דהב\u0004 \u0005[זהב].\u0006 ושואלים: \u0003אימא נסכא\u0004 \u0005[אמור\u0006 שמדובר ב\u0005חתיכה קטנה\u0006 של זהב\u0005]!\u0006 \u0003אמר ר' אלעזר:\u0004 מדובר \u0003דכתב\u0004 \u0005[שכתוב]\u0006 בשטר \u0003\"מטבע\".\u0004"],["ושואלים: \u0003ואימא פריטי\u0004 \u0005[ואמור\u0006 שהכוונה ל\u0005פרוטות\u0006 של זהב\u0005]!\u0006 ומשיבים: \u0003פריטי דדהבא\u0004 \u0005[פרוטות של זהב]\u0006 \u0003לא עבדי אינשי\u0004 \u0005[עושים אנשים]\u0006 כלל.","ועוד שנינו בברייתא: \u0003\"זהב בדינרין\"\u0004 — \u0003אין פחות מב\u0004 שווי \u0003שני דינרין כסף,\u0004 שמשלם ב\u0003זהב.\u0004 ושואלים: \u0003ואימא דהבא פריכא בתרי דינרי דהבא קאמר\u0004 \u0005[ואמור חתיכות זהב ב\u0006שווי \u0005שני דינרי זהב אמר],\u0006 שלכך התכוון בדבריו! \u0003אמר אביי: יד בעל השטר על התחתונה,\u0004 ומפרשים את השטר לפי הסכום הנמוך ביותר.","ושואלים: אם כן, \u0003רישא דקתני\u0004 \u0005[בהתחלה,\u0006 בברייתא הראשונה, \u0005ששנינו]:\u0006 \u0003\"כסף בדינרין\"\u0004 — \u0003אין פחות מ\u0004שווי \u0003שני דינרין זהב,\u0004 ומשלם \u0003כסף, אמאי\u0004 \u0005[מדוע]?\u0006 \u0003אימא כספא נסכא בתרי דינרי כספא קאמר\u0004 \u0005[אמור\u0006 שהתכוון ל\u0005כסף, חתיכה\u0006 של כסף \u0005ב\u0006שווי \u0005שני דינרי כסף אמר]!\u0006","\u0003אמר רב אשי: רישא\u0004 \u0005[בתחילה,\u0006 בברייתא הראשונה\u0005]\u0006 מדובר \u0003דכתב\u0004 \u0005[שכתוב]\u0006 בשטר \u0003\"דינרי\"\u0004 (\"כסף בדינרי\"), שמשמעו דינרי זהב. \u0003סיפא\u0004 \u0005[בסוף,\u0006 בברייתא השניה\u0005]\u0006 מדובר \u0003דכתב\u0004 \u0005[שכתוב]\u0006 בשטר \u0003\"דינרין\",\u0004 שמשמעו דינרי כסף.","\u0003ומנא תימרא דשאני\u0004 \u0005[ומנין תאמר ששונה,\u0006 שיש הבדל\u0005],\u0006 \u0003בין \"דינרי\" ל\"דינרין\"?\u0004","— \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האשה שהיו עליה ספק חמש לידות,\u0004 שהפילה, ואינה יודעת אם היא חייבת להביא קרבן יולדת. או שהיו עליה \u0003ספק חמש זיבות,\u0004 שאינה בטוחה אם דם זיבה ראתה וצריכה להביא קרבן, או רק דם נדה ראתה, ואינה צריכה. וכל זמן שלא הביאה היולדת או הזבה קרבנה — אינה רשאית לאכול מבשר קדשים — \u0003מביאה קרבן אחד ואוכלת בזבחים, ואין השאר עליה חובה,\u0004 אלא אם רוצה מביאה. אבל אם \u0003היו עליה חמש לידות ודאות,\u0004 או \u0003חמש זיבות ודאות\u0004 — \u0003מביאה קרבן אחד ו\u0004מאותה שעה \u0003אוכלת בזבחים\u0004 מכוחו, אבל שלא כמו במקרה של ספק — \u0003השאר עליה חובה.\u0004","\u0003מעשה ועמדו,\u0004 שנקבע בשוק שער המכירה של \u0003קינים\u0004 (זוג של תורים או יונים שמביאים לטהרת היולדת והזבה) \u0003בירושלים בדינרי זהב,\u0004 שהסוחרים הפקיעו את מחיריהם בגלל הביקוש הרב שהיה אז לקינים, והיה קשה לנשים להביא קינים כדי להיטהר. \u0003אמר רבן שמעון בן גמליאל\u0004 בלשון שבועה: \u0003המעון הזה!\u0004 שנשבע בבית המקדש: אני נשבע \u0003אם אלין הלילה עד שיהו\u0004 מחיריהם של הקינים \u0003בדינרין. נכנס לבית דין ולימד: האשה שהיו עליה חמש לידות ודאות,\u0004 או \u0003חמש זיבות ודאות\u0004 — \u0003מביאה קרבן אחד ואוכלת בזבחים, ואין השאר עליה חובה.\u0004"],["\u0003עמדו קינין בו ביום ברבעתים\u0004 ברביעיות של דינר, שירד המחיר הרבה מאד.","שנינו במשנה שאם \u0003כתוב מלמעלה\u0004 מנה ולמטה מאתיים הולכים אחר התחתון. אם כן למה כותבים את העליון? — שאם תימחק אות אחת מן התחתון ילמד מן העליון. ועל כך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מתי \u0003ילמד התחתון מן העליון\u0004 — \u0003ב\u0004זמן שיש \u0003אות אחת\u0004 מחוקה, \u0003אבל לא\u0004 \u0003בשתי אותיות,\u0004 ומהי הדוגמא לאות אחת —","\u0003כגון\u0004 בשמות אנשים שנשאר למטה \u0003\"חנן\" מ\"חנני\", ו\u0004כן \u0003\"ענן\" מ\"ענני\",\u0004 אבל לא \"חן\" מ\"חנני\".","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 הבדל של \u0003שתי אותיות,\u0004 ש\u0003לא\u0004 סומכים? — שיש לחשוש \u0003דלמא מיתרמי\u0004 \u0005[שמא מזדמן]\u0006 \u0003שם בן ארבע אותיות, והוה ליה פלגיה דשמא\u0004 \u0005[והרי זה חצי שם]\u0006 שלמדים מן העליון, והרי אין למדים מן העליון. \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אות אחת\u0004 שנמחקה \u0003נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש, \u0003דלמא מיתרמי\u0004 \u0005[שמא מזדמן]\u0006 \u0003שם בן שתי אותיות, והוה ליה פלגיה דשמא\u0004 \u0005[והרי זה חצי שם]!\u0006","\u0003אלא, שתי אותיות היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 שאין סומכים על כך, \u0003דלמא מיתרמי\u0004 \u0005[שמא מזדמן]\u0006 \u0003שם בן שלש אותיות, והוה ליה רובא דשמא\u0004 \u0005[והרי זה רוב השם],\u0006 אבל אות אחת לעולם אינה יכולה להיות רובו של שם.","\u0003אמר רב פפא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי,\u0004 אם היה כתוב \u0003\"ספל\" מלמעלה ו\"קפל\" מלמטה\u0004 — \u0003הכל הולך אחר התחתון.\u0004","אולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם היה כתוב \u0003\"קפל\" מלמעלה ו\"ספל\" מלמטה, מאי\u0004 \u0005[מה]\u0006 הדין? \u0003מי חיישינן\u0004 \u0005[האם אנו חוששים]\u0006 \u0003לזבוב\u0004 שמחק מעט, ונראה הק' כמו ס', \u0003או לא?\u0004 שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","מסופר: \u0003ההוא דהוה כתב ביה שית מאה וזוזא\u0004 \u0005[\u0006שטר \u0005אחד שהיה כתוב בו שש מאות וזוז],\u0006 \u0003שלחה\u0004 לשאלה זו \u0003רב שרביא קמיה\u0004 \u0005[לפני]\u0006 \u0003אביי:\u0004 כיצד יש לפרש את לשון השטר? האם הכוונה היא ל\u0003שית מאה איסתירי וזוזא\u0004 \u0005[שש מאות סלעים וזוז],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא ל\u0003שית מאה פריטי וזוזא\u0004 \u0005[שש מאות פרוטות וזוז]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דל פריטי\u0004 \u0005[הוצא פרוטות]\u0006 מן השיקול, \u0003דלא כתבי בשטרא\u0004 \u0005[שאין כותבים\u0006 אותם \u0005בשטר],\u0006 \u0003דאסוכי מסכן להו\u0004 \u0005[שמסכם אותן]\u0006"],["\u0003ומשוי להו זוזי\u0004 \u0005[ועושה אותם לזוזים],\u0006 \u0003מאי אמרת\u0004 \u0005[מה אומר אתה]?\u0006 \u0003שית מאה איסתירי וזוזא\u0004 \u0005[שש מאות סלעים וזוז],\u0006 או שמא \u0003שית מאה זוזי וחד זוזא\u0004 \u0005[שש מאות זוזים ו\u0006עוד \u0005זוז אחד]\u0006 — \u0003יד בעל השטר על התחתונה\u0004 ומפרשים לפי הסכום הקטן.","ועוד בענייני כתיבת שטרות והזהירות בדרכי הכתיבה והמחיקה של השטר. \u0003אמר אביי: האי מאן דבעי למחוי חתימות ידיה בבי דינא\u0004 \u0005[מי שצריך להראות\u0006 את \u0005חתימת ידו בבית דין]\u0006 כדי שיוכלו הדיינים לאמת את חתימתו שבשטר על ידי השוואתה לחתימתו זו, \u0003לא לחוי\u0004 \u0005[יראה]\u0006 את חתימתו \u0003בסוף מגילתא\u0004 \u0005[מגילה],\u0006 או נייר, \u0003דלמא משכח לה אחר וכתיב דמסיק ביה זוזי\u0004 \u0005[שמא ימצא אותה\u0006 את המגילה הזו אדם \u0005אחר, ויכתוב ש\u0006הוא \u0005נושה בו כסף],\u0006 ויגבה על סמך שטר זה, \u0003ותנן\u0004 \u0005[ו\u0006כפי ש\u0005שנינו\u0006 במשנה\u0005]:\u0006 אם \u0003הוציא עליו כתב ידו שהוא חייב לו\u0004 — \u0003גובה מנכסים בני חורין,\u0004 ומוטב שיזהר בכך.","ובענין זה מסופר: \u0003ההוא בזבינא דאתא לקמיה\u0004 \u0005[מוכס אחד\u0006 יהודי \u0005שבא לפני]\u0006 \u0003אביי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ניחזי\u0004 \u0005[יראה]\u0006 \u0003לי מר\u0004 \u0005[אדוני]\u0006 את \u0003חתימות ידיה\u0004 \u0005[ידו],\u0006 \u0003דכי אתו רבנן מחוו\u0004 \u0005[שכאשר יבואו חכמים\u0006 ו\u0005יראו]\u0006 \u0003לי\u0004 את חתימתך \u0003מעברנא להו\u0004 \u0005[אעביר אותם]\u0006 \u0003בלא\u0004 לקחת מהם \u0003מכסא\u0004 \u0005[מכס],\u0006 וצריך אני לשם כך שתהא בידי חתימתך. \u0003אחוי ליה בריש מגילתא\u0004 \u0005[הראה לו\u0006 אביי, כתב את שמו \u0005בראש המגילה],\u0006 \u0003הוה קא נגיד ביה\u0004 \u0005[היה\u0006 אותו אדם \u0005מושך בה]\u0006 כדי להרחיק את החתימה למטה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי, שהבין מה הוא זומם: \u0003כבר קדמוך רבנן\u0004 \u0005[חכמים],\u0006 שאמרו שצריך להיזהר בכך, ולא לחתום בסופה של מגילה.","\u0003אמר אביי:\u0004 כשכותב סופר בשטר סכום \u0003מתלת\u0004 \u0005[משלוש]\u0006 \u0003ועד עשר\u0004 — \u0003לא לכתוב\u0004 \u0005[יכתוב]\u0006 \u0003בסוף שיטה\u0004 (שורה), \u0003דלמא מזייף וכתב\u0004 \u0005[שמא יזייף\u0006 בעל השטר \u0005ויכתוב]\u0006 ויוסיף למספר הכתוב סיומת של צורת רבים, ובמקום \"שלוש\" יהא כתוב \"שלושים\", וכיוצא בזה. \u0003ואי איתרמי ליה\u0004 \u0005[ואם הזדמן לו]\u0006 בכל זאת מספר כזה בסוף שורה, \u0003ניהדריה לדבוריה תרין תלתא זימני\u0004 \u0005[שיחזור על דיבורו שתים שלוש פעמים],\u0006 כלומר, יחזור ויכתוב שוב מספר זה כמה פעמים, והרי \u0003אי אפשר\u0004 באופן זה ש\u0003לא מיתרמי ליה\u0004 \u0005[יזדמן לו]\u0006 שיוזכר המספר הזה \u0003באמצע שיטה,\u0004 ואז כבר לא יוכל המחזיק בשטר לזייפו.","ועוד בענייני זיופי שטרות, מסופר: \u0003ההוא דהוה כתיב ביה תילתא בפרדיסא\u0004 \u0005[\u0006שטר \u0005אחד שהיה כתוב בו\u0006 שמכר המוכר מנכסיו \u0005שליש בפרדס],\u0006 \u0003אזל מחקיה לגגיה\u0004 \u0005[הלך\u0006 הקונה ו\u0005מחק את גגו]\u0006 של ה\u0003בי\"ת וכרעיה\u0004 \u0005[ו\u0006את \u0005רגלו],\u0006 \u0003ושויה\u0004 \u0005[ועשה אותו]\u0006 ו', כאילו היה כתוב בשטר שנמכרו מהנכסים \u0003\"\u0004תילתא \u0003ופרדיסא\"\u0004 \u0005[\u0006שליש \u0005ופרדס],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הקונה \u0005לפני]\u0006 \u0003אביי\u0004 לתבוע לפי מה שכתוב בשטר, שהוא מקבל שליש מן הנכסים ופרדס, \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003מאי טעמא רויח ליה עלמא להאי וי\"ו\u0004 \u0005[מה הטעם\u0006 ש\u0005מרווח לו המקום לוי\"ו הזה]?\u0006 \u0003כפתיה ואודי\u0004 \u0005[כפת אותו והודה]\u0006 שהיה זה זיוף.","ועוד מסופר, \u0003ההוא דהוה כתב ביה\u0004 \u0005[\u0006שטר \u0005אחד שהיה כתוב בו]\u0006 שקנה \u0003\"מנת\u0004 \u0005[\u0006את \u0005החלק]\u0006 של \u0003ראובן ושמעון אחי\u0004 \u0005[האחים]\u0006 \u0003\".\u0004 \u0003הוה להו אחא דשמיה\u0004 \u0005[היה להם אח ששמו\u0006 היה\u0005]\u0006 \u0003\"אחי\", אזל\u0004 \u0005[הלך]\u0006 המחזיק בשטר \u0003כתב ביה\u0004 \u0005[בו]\u0006 \u0003וי\"ו, ושויה\u0004 \u0005[ועשה אותו]\u0006 כתוב \u0003\"ואחי\",\u0004 כאילו קנה גם את החלקה של אחיהם. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003אביי\u0004 עם שטרו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא דחיק ליה עלמא להאי וי\"ו כולי האי\u0004 \u0005[מה הטעם צר לו המקום לוי\"ו הזה כל כך]\u0006 שהרי היה צריך לדחוק את תוספת האות וי\"ו בין המילים, \u0003כפתיה ואודי\u0004 \u0005[כפת אותו והודה]\u0006 שהיה זה זיוף.","ועוד מסופר, \u0003ההוא שטרא דהוה חתים עליה\u0004 \u0005[שטר אחד שהיו חתומים עליו]\u0006 \u0003רבא ורב אחא בר אדא. אתא לקמיה\u0004 \u0005[בא\u0006 בעל השטר \u0005לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003דין חתימות ידא דידי\u0004 \u0005[זוהי\u0006 אכן \u0005חתימת ידי שלי]\u0006 \u0003היא, מיהו קמיה\u0004 \u0005[אבל לפני]\u0006 \u0003רב אחא בר אדא\u0004 שהוא מבוגר ממני בהרבה, \u0003לא חתימי לי\u0004 \u0005[חתמתי]\u0006 \u0003מעולם,\u0004 שתמיד חתמתי אחריו! ואם כן ברור לי שזיוף הוא. \u0003כפתיה ואודי\u0004 \u0005[כפתו והודה]\u0006 שזייף. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לאותו זייפן: \u0003בשלמא דידי\u0004 \u0005[נניח\u0006 את כתב ידי \u0005שלי]\u0006 \u0003זייפת, אלא\u0004 את חתימתו של \u0003רב אחא בר אדא דרתית ידיה\u0004 \u0005[שהיו רוטטות ידיו]\u0006 מחמת זקנה, \u0003היכי עבדת\u0004 \u0005[איך\u0006 הצלחת \u0005לעשות]\u0006 שייראה כך? \u0003אמר:\u0004 בשעה שזייפתי את חתימתו \u0003אנחי ידאי אמצרא\u0004 \u0005[הנחתי את ידי על חבל המתוח בין שתי גדות הנהר]\u0006 שאנשים אוחזים בו, והוא מתנדנד כל הזמן. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003קם אזרנוקא\u0004 \u0005[עמד על נאד]\u0006 \u0003וכתב\u0004 כשהוא מתנודד עליו, ומתאמץ שלא ליפול.","\u0003כותבין גט לאיש אף על פי שאין אשתו עמו,\u0004 לפי שמדין תורה אין הגט תלוי אלא בדעת הבעל. \u0003ו\u0004כן כותבים את \u0003השובר\u0004 (קבלה) עבור ה\u0003אשה\u0004 שנתגרשה, בו היא מאשרת שקיבלה את כתובתה — \u0003אף על פי שאין בעלה עמה, ובלבד שיהא מכירן\u0004 את מי שמבקש ממנו לכתוב, ושאין זו רמאות. \u0003והבעל נותן שכר\u0004 על כתיבת הגט והשובר."],["וכן \u0003כותבין שטר\u0004 חוב \u0003ללוה אף על פי שאין מלוה עמו,\u0004 ואין חוששים, שהרי הלווה הוא זה שמחייב את עצמו, ואין בדבר אלא זכות למלוה. \u0003ו\u0004אולם \u0003אין כותבין\u0004 שטר חוב \u0003למלוה עד שיהא לוה עמו\u0004 שיסכים לכתיבת השטר. \u0003ו\u0004בכל שטר הלוואה \u0003הלוה\u0004 הוא ה\u0003נותן שכר\u0004 כתיבת שטר החוב.","\u0003כותבין שטר\u0004 מכירה \u0003למוכר אף על פי שאין לוקח\u0004 (קונה) \u0003עמו,\u0004 משום שהוא מחייב רק את עצמו בשטר הזה, \u0003ו\u0004אולם \u0003אין כותבין ללוקח עד שיהא מוכר עמו. והלוקח נותן שכר\u0004 כתיבת שטר המכירה.","\u0003אין כותבין שטרי אירוסין ונשואין אלא מדעת שניהם, והחתן נותן שכר\u0004 הכתיבה.","\u0003אין כותבין שטר אריסות וקבלנות\u0004 על שדה \u0003אלא מדעת שניהם. והמקבל,\u0004 כלומר, האריס \u0003נותן שכר.\u0004","\u0003אין כותבין שטרי בירורין\u0004 (שיבואר עניינם בגמרא) \u0003וכל מעשה בית דין, אלא מדעת שניהם, ו\u0004בשטרי בירורין \u0003שניהם נותנין שכר\u0004 הכתיבה. \u0003רבן שמעון בן גמליאל אומר: לשניהם כותבין\u0004 שטרי בירורין, \u0003שנים, לזה לעצמו ולזה לעצמו.\u0004","שנינו במשנה שכותבים גט לאיש בלא האשה ושובר לאשה בלא האיש, ובלבד שיהא מכירן. ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ובלבד שיהא מכירן\"? אמר רב יהודה אמר רב: ובלבד שיהא מכיר שם האיש\u0004 שלפניו, שהוא כותב עבורו \u0003בגט, ו\u0004כן שיכיר את \u0003שם האשה בשובר.\u0004","מסופר: \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב ספרא ורב אחא בר הונא ורב הונא בר חיננא, ויתיב\u0004 \u0005[ויושב\u0006 היה\u0005]\u0006 \u0003אביי גבייהו\u0004 \u0005[איתם],\u0006 \u0003ויתבי וקמיבעיא להו\u0004 \u0005[והיו יושבים\u0006 ודנים בענין זה, \u0005ונשאלה להם שאלה\u0006 זו במשנתנו\u0005]:\u0006 וכי את \u0003שם האיש בגט\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 צריך להכיר, \u0003שם האשה\u0004 — \u0003לא\u0004 חייב להכיר? וכיוצא בזה, \u0003שם האשה בשובר\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 צריך להכיר, \u0003שם האיש\u0004 — \u0003לא\u0004 צריך להכיר?","\u0003וליחוש דלמא\u0004 \u0005[ונחשוש שמא]\u0006 \u0003כתב\u0004 האיש הזה \u0003גיטא\u0004 \u0005[גט],\u0006 והסופר יודע את שמו אבל לא את שם אשתו, והוא יצוה לכתוב גט ויכתוב בו שמה של אשה שאינה אשתו, \u0003ואזיל וממטי ליה לאיתתיה דהיאך\u0004 \u0005[וילך ויביא אותו לאשתו של אחר]\u0006 ששמו כשמו, והיא יוצאת מבעלה שלא כדין.","וכיוצא בזה בענין שובר, \u0003זמנין אזלא כתבה\u0004 \u0005[פעמים הולכת\u0006 ו\u0005כותבת]\u0006 ה\u0003אשה שובר\u0004 שהתקבלה כתובתה, והסופר יודע את שמה אבל אינו יודע שם בעלה, והיא אומרת לו לכתוב שמו של אדם אחר ששם אשתו כשמה, והיא הולכת \u0003ויהבה\u0004 \u0005[ונותנת]\u0006 את השובר \u0003לגברא דלאו דילה\u0004 \u0005[ל\u0006אותו \u0005אדם שאינו\u0006 בעלה \u0005שלה]\u0006 כדי שעל ידי כך ייפטר מלשלם לאשתו את כתובתה!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב:\u0004 ובלבד שיהא מכיר \u0003שם האיש בגט, והוא הדין לשם האשה; שם האשה בשובר, והוא הדין לשם האיש.\u0004","ושאלו: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003לשני יוסף בן שמעון הדרים בעיר אחת,\u0004 כלומר, שני אנשים שיש להם ולנשותיהם אותם שמות, ויש לחשוש \u0003דלמא כתיב גיטא ואזיל וממטי ליה לאיתתיה דהיאך\u0004 \u0005[שמא יכתוב\u0006 אחד מהם \u0005גט וילך ויביא אותו לאשתו של האחר]!\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב אחא בר הונא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: שני יוסף בן שמעון הדרים בעיר אחת, אין מגרשין נשותיהן אלא זה בפני זה,\u0004 ולכן אין לחשוש לכך. ועוד שאלו על דין המשנה: מה תועיל הכרת שם האיש (והאשה) שבגט?","\u0003וליחוש דלמא אזיל למתא אחריתא ומחזיק ליה לשמיה\u0004 \u0005[ונחשוש שמא ילך\u0006 אדם \u0005לעיר אחרת ויחזיק\u0006 עצמו \u0005ששמו הוא]\u0006 \u0003יוסף בן שמעון, וכתיב גיטא וממטי ליה לאיתתיה דהיאך\u0004 \u0005[ויכתוב\u0006 שם \u0005גט ויביא אותו לאשתו של האחר]\u0006 ששמו באמת יוסף בן שמעון (ושם אשתו כשם אשתו של זה)!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב הונא בר חיננא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: כל שהוחזק שמו בעיר שלשים יום\u0004 — \u0003אין חוששין לו\u0004 שיש לו שם אחר.","ושואלים: ואם השם \u0003לא איתחזק\u0004 \u0005[הוחזק],\u0006 \u0003מאי?\u0004 \u0005[מהו]?\u0006 כיצד יודעים שאדם המציג עצמו בשם מסויים, אכן זה שמו? \u0003אמר אביי: דקרו ליה ועני\u0004 \u0005[שקוראים לו\u0006 בשם זה \u0005ו\u0006הוא \u0005עונה].\u0006 \u0003רב זביד אמר: רמאה ברמאותיה זהיר\u0004 \u0005[רמאי ברמאותו נזהר]\u0006 ואין לסמוך על כך. ואין לו תקנה עד שישהה במקום.","מסופר: \u0003ההוא תברא דהוה חתים עלה\u0004 \u0005[שובר אחד שהיה חתום עליו]\u0006 \u0003רב ירמיה בר אבא, אתיא לקמיה ההיא איתתא\u0004 \u0005[באה לפניו אשה אחת],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אנא הואי\u0004 \u0005[לא אני הייתי\u0006 זו\u0005]\u0006 שכתבה את השובר, אלא אשה אחרת התיימרה להיות אני, ואני עצמו לא קיבלתי כתובה. \u0003אמר: אנא נמי אמרי להו\u0004 \u0005[אני גם כן אמרתי להם]\u0006 לאלה שהיו אתי בזמן שבאה אותה אשה: \u0003לאו איהי\u0004 \u0005[לא זו]\u0006 \u0003היא,\u0004 \u0003ואמרו לי: מיקש הוא דקשא לה ובגר לה קלא\u0004 \u0005[הזדקנה\u0006 במשך הזמן \u0005ונעשה קולה עבה].\u0006","\u0003אמר אביי, אף על גב דאמור רבנן\u0004 \u0005[אף על פי שאמרו חכמים]:\u0006"],["\u0003כיון שהגיד,\u0004 כלומר, אחרי שהעיד אדם עדותו בבית דין \u0003שוב אינו חוזר ומגיד,\u0004 ואין אדם יכול לחזור בו מעדותו, מכל מקום \u0003צורבא מרבנן לאו אורחיה למידק\u0004 \u0005[תלמיד חכם אין דרכו לדקדק\u0006 להבחין בבירור בנשים\u0005]\u0006 ולכן יש מקום לומר שרימו את ר' ירמיה בר אבא באותו שעה, והוא נאמן על מה שהוא אומר.","ועוד סיפור דומה, \u0003ההוא תברא דהוה חתים עליה\u0004 \u0005[שובר אחד שהיה חתום עליו]\u0006 \u0003רב ירמיה בר אבא\u0004 כעד\u0003,\u0004 ולאחר זמן באה האשה שנכתב שמה באותו שובר כמי שקיבלה את כתובתה, \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אנא הואי\u0004 \u0005[לא אני הייתי\u0006 זאת\u0005]\u0006 שכתבתם לה את השובר, אלא אשה אחרת חתמה בשמי, ונתנה לבעלי, ואני לא קיבלתי את כתובתי. \u0003אמר לה: איברא אנת הות\u0004 \u0005[באמת את היית]\u0006 זו. \u0003אמר אביי: אף על גב דצורבא מרבנן לאו אורחיה למידק\u0004 \u0005[אף על פי שתלמיד חכם אין דרכו לדקדק],\u0006 \u0003כיון דדק\u0004 \u0005[שדקדק]\u0006 — \u0003דק\u0004 \u0005[דקדק],\u0006 וסומכים עליו.","ואגב כך \u0003אמר אביי: האי צורבא מרבנן דאזיל לקדושי איתתא\u0004 \u0005[תלמיד חכם שהולך לקדש אשה],\u0006 ראוי ש\u0003נידבר\u0004 \u0005[שיקח]\u0006 \u0003עם הארץ\u0004 \u0003בהדיה\u0004 \u0005[איתו],\u0006 \u0003דלמא מחלפו לה מיניה\u0004 \u0005[שמא יחליפו לו אותה],\u0006 שיסמכו על כך שאין דרכו להסתכל בנשים, ויתנו לו אישה אחרת. ולכן יקח עימו אדם שדרכו להסתכל בנשים.","שנינו במשנה: \u0003והבעל נותן שכר\u0004 הגט. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכתב\u0004 גט כריתות\u0003... ונתן\u0004 בידה\u0003\"\u0004 (דברים כד, א), משמע שהוא צריך לכתוב, משלו. ומעירים: \u0003והאידנא דלא עבדינן הכי\u0004 \u0005[ועכשיו שאין אנו עושים כך]\u0006 אלא האשה היא המשלמת את שכר כתיבת הגט, הרי משום ש\u0003שדיוהו רבנן\u0004 \u0005[הטילוהו\u0006 את שכר כתיבת הגט \u0005חכמים]\u0006 על ה\u0003אשה כי היכי\u0004 \u0005[כדי]\u0006 שהבעל \u0003לא לשהייה\u0004 \u0005[ישהה אותו,\u0006 את הגט\u0005]\u0006 בגלל עניינים של כסף, ויגרום לה להישאר עגונה.","שנינו במשנה ש\u0003כותבין שטר ללוה אף על פי שאין מלוה עמו\u0004 והלווה משלם עבור השטר. ואומרים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, שהרי הוא הזקוק להלוואה ומרויח ממנה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003בעיסקא\u0004 שהם עושים שותפות ביניהם בכסף זה, לומר שאף על פי שיש בכך צד רווח גם למלוה, מכל מקום בעיקרו של דבר הלוואה היא, ועיקר ההנאה הוא ללווה.","ועוד שנינו במשנה ש\u0003כותבין שטר למוכר אף על פי שאין לוקח\u0004 עמו, והקונה משלם עבור השטר. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 מובן מאליו שהקונה הוא המשלם, שהרי הוא הזוכה בדבר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003במוכר שדהו מפני רעתה,\u0004 שאפשר היה לחשוב שהנאה היא למוכר המצליח להיפטר מן השדה.","עוד שנינו במשנה ש\u0003אין כותבין שטרי אירוסין\u0004 אלא מדעת שניהם, והחתן נותן שכר. ואומרים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, שהרי שטר שיש בו תנאים משני הצדדים — צריכים שניהם להסכים עליו. וגם הדין שהחתן ישלם — פשוט הוא, שהרי הוא המקדש או הנושא אשה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לומר ש\u0003אפילו\u0004 היה זה \u0003צורבא מרבנן\u0004 \u0005[תלמיד חכם],\u0006 \u0003דניחא ליה לחמוה לקרוביה\u0004 \u0005[שנוח לו לחמיו לקרב אותו],\u0006 והיה מקום לומר שאולי יכול החתן לכתוב את השטר לבדו, וכן דמי השטר יהיו על משפחת הכלה. לכן נאמר שבכל מקרה הדין כן.","ועוד שנינו במשנה ש\u0003אין כותבין שטר אריסות וקבלנות\u0004 אלא מדעת שניהם, ושניהם משלמים עבור השטר. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לומר שאפילו \u0003ב\u0004שדה \u0003בורה,\u0004 שאפשר היה לחשוב שבעל השדה מעוניין להשכיר יותר משהאריס רוצה לשכור, הדין כן.","שנינו במשנה ש\u0003אין כותבין שטרי בירורין אלא מדעת שניהם.\u0004 ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שטרי בירורין\"? הכא תרגימו\u0004 \u0005[כאן\u0006 בבבל \u0005תרגמו]:\u0006 \u0003שטרי טענתא\u0004 \u0005[טענות],\u0006 כלומר, מסמך שכותבים בו בית הדין מה טוען כל אחד מהצדדים, כדי שלא יוכלו לחזור בהם ולטעון דברים אחרים. \u0003רב ירמיה בר אבא אמר:\u0004 הכוונה היא למקרה בו אין שני הצדדים מסכימים מי ידון ביניהם, ואז \u0003זה בורר לו\u0004 דיין \u0003אחד וזה בורר לו אחד\u0004 ושני הדיינים בוררים להם דיין שלישי שידון איתם. ואת הענין הזה צריכים לכתוב, כדי שלא יוכלו לחזור בהם, ומשום כך גם לא ניתן לכותבו שלא מדעת שניהם.","עוד שנינו במשנה ש\u0003רבן שמעון בן גמליאל אומר:\u0004 אם רצה אחד מהם, \u0003לשניהם כותבין שנים,\u0004 כלומר, כותבים שני שטרי בירורין, \u0003לזה בעצמו ולזה בעצמו.\u0004 ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 בהסבר מחלוקתם, ש\u0003ב\u0004שאלה העקרונית, האם בית דין \u0003כופין על מדת סדום קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 וכגון כאן, שאדם מסרב להשתתף בשטר אחד בו מצויות טענות שניהם, למרות שאינו מפסיד בכך דבר, בטענה שרצונו בשטר לעצמו,","\u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 תנא קמא, \u0005סבור]\u0006 \u0003כופין\u0004 על מדת סדום, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003אין כופין\u0004 וזכותו לסרב להשתתף בתשלום שכר הסופר?","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 בדרך כלל \u0003כופין\u0004 על מדת סדום, \u0003והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 של \u0003רבן שמעון בן גמליאל,\u0004 שמה שאין אחד מהם רוצה בשטר משותף אינו מדת סדום, לפי שטענה של ממש יש לו — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 לשני: \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דתהוי\u0004 \u0005[שתהיה]\u0006 \u0003זכותך,\u0004 טענותיך, \u0003גבי\u0004 \u0005[אצל,\u0006 ליד\u0005]\u0006 \u0003זכותי,\u0004 משום \u0003דדמית עלאי כי אריא ארבא\u0004 \u0005[שדומה אתה עלי כאריה אורב].\u0006","\u0003מי שפרע מקצת חובו,\u0004 ולא נכתב על אותו סכום, ומצד שני לא קרעו את השטר, שהרי לא נפרע כולו, \u0003והשליש\u0004 (הפקיד) \u0003את שטרו\u0004 ביד אדם שלישי, על מנת להבטיח ללווה שלא יחזור ויתבע המלוה את כל הסכום. \u0003ואמר לו\u0004 הלווה לשליש: \u0003\"אם לא נתתי לך מכאן\u0004 (מעכשיו) \u0003ועד יום פלוני\u0004 את שאר הכסף \u0003תן לו\u0004 למלוה את \u0003שטרו\",\u0004 למרות שיוכל לחזור ולגבות את כולו, אם \u0003הגיע\u0004 ה\u0003זמן\u0004 שקבע \u0003ולא נתן\u0004 — \u0003ר' יוסי אומר: יתן\u0004 השליש כמו שהתנה הלווה עמו. \u0003ר' יהודה אומר: לא יתן.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומשיבים: \u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003אסמכתא קניא\u0004 \u0005[קונה],\u0006 כלומר, שאם אדם מבטיח דבר על תנאי שהוא סבור שלא יתקיים, כיון שהתקיים התנאי — חלה ההתחייבות. כגון כאן, שהיה הלווה בטוח שיפרע את שאר החוב עד אותו זמן, אלא שנתבדה. \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003אסמכתא לא קניא\u0004 \u0005[אינה קונה],\u0006 ואין זו נחשבת כהתחייבות של ממש.","\u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: הלכה כר' יוסי\u0004 שאסמכתא קונה. \u0003כי אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003ר' אמי\u0004 בענין דין אסמכתא, \u0003אמר להו\u0004 \u0005[היה אומר להם]:\u0006 \u0003וכי מאחר שר' יוחנן מלמדנו פעם ראשונה ושניה\u0004 ש\u0003הלכה כר' יוסי, אני מה אעשה?\u0004 איך אפסוק שלא כדעת ר' יוחנן.","ומסכמים: ובכל זאת \u0003אין הלכה כר' יוסי,\u0004 שלא נתקבלה דעתו להלכה.","\u0003מי שנמחק שטר חובו\u0004 כגון שנפל למים וניטשטש — \u0003מעמיד עליו עדים\u0004 שיודעים מה היה כתוב בו, \u0003ובא\u0004 עם עדיו \u0003לפני בית דין, ועושין לו קיום\u0004 לשטר הזה, וכותבים כך: \u0003\"איש פלוני בן פלוני נמחק שטרו ביום פלוני,\u0004"],["\u0003ופלוני ופלוני\u0004 הם \u0003עדיו\u0004 בענין זה.","על ענין זה שבמשנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו\u0004 (כיצד הוא) \u0003קיומו\u0004 של שטר מחוק? — כותבים על פי העדים את תוכנו, ולאחר מכן כותבים בו כך: \u0003\"במותב תלתא הוינא\u0004 \u0005[במושב שלושה\u0006 דיינים \u0005היינו]\u0006 \u0003אנו פלוני ופלוני ופלוני,\u0004 ואז \u0003הוציא פלוני בן פלוני שטר מחוק לפנינו ביום פלוני, ופלוני ופלוני עדיו\"; ואם כתוב בו\u0004 בנוסח הקיום הזה: \u0003\"הוזקקנו\u0004 (נדרשנו) \u0003לעדותן של\u0004 ה\u0003עדים\u0004 \u0003ונמצאת עדותן מכוונת\u0004 (תואמת) \u0003\"\u0004— \u0003גובה\u0004 בשטר זה, \u0003ואינו צריך להביא ראיה\u0004 לאמיתותו של השטר. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שלא נכתב כגון דבר זה — \u0003צריך\u0004 המלוה \u0003להביא ראיה\u0004 לאמיתותו של השטר, כדי לגבות בו.","ובענין שטר שהובא לבית דין כדי שיקיימוהו, אם \u0003נקרע\u0004 השטר בכוונה — הרי זה \u0003פסול, נתקרע\u0004 מעצמו — \u0003כשר;\u0004 \u0003נמחק או נטשטש\u0004 השטר, \u0003אם\u0004 עדיין \u0003רישומו\u0004 של הכתב הראשון \u0003ניכר\u0004 — \u0003כשר.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003נקרע, היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003נתקרע? אמר רב יהודה: נקרע,\u0004 כוונתו \u0003קרע של בית דין\u0004 שהם קורעים שטר שכבר אין לו תוקף, \u0003נתקרע\u0004 — כוונתו \u0003קרע שאינו של בית דין.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003קרע של בית דין? אמר רב יהודה:\u0004 שהם קורעים את \u0003מקום עדים ומקום הזמן ומקום התורף\u0004 (עיקרו של השטר — שמות הצדדים וסכום ההלוואה. וכיוצא בזה בשטר המכר). \u0003אביי אמר:\u0004 קרע בית דין הוא בצורת \u0003שתי וערב.\u0004","ודנים עוד בענין כתיבה נוספת של השטר. מסופר: \u0003הנהו ערבאי דאתו\u0004 \u0005[אותם ערבים שבאו]\u0006 \u0003לפומבדיתא, דהוו קא אנסי ארעתא דאינשי\u0004 \u0005[שהיו אונסים,\u0006 גוזלים \u0005קרקעות של בני אדם],\u0006 וגם היו מכריחים למסור להם את שטרי המכר שלהם, על מנת שלא תהיה בידי הבעלים ראיה לבעלותם על הקרקע. \u0003אתו מרוותיהו לקמיה\u0004 \u0005[באו בעלי\u0006 השדות \u0005לפני]\u0006 \u0003אביי, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ליחזי מר שטרין\u0004 \u0005[שיראה אדוני\u0006 את \u0005השטר שלנו]\u0006 \u0003ולכתוב לן מר שטרא אחרינא עליה\u0004 \u0005[ויכתוב לנו אדוני שטר אחר עליו],\u0006 \u0003דאי מיתניס חד\u0004 \u0005[שאם ייאנס,\u0006 י ילקח בכח \u0005אחד\u0006 מן השטרות\u0005]\u0006 \u0003נקיטינן חד בידן\u0004 \u0005[נחזיק\u0006 שטר \u0005אחד בידינו].\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי אעביד לכו\u0004 \u0005[מה אעשה לכם]?\u0006 ש\u0003אמר רב ספרא: אין כותבין שני שטרות על שדה אחת, דלמא\u0004 \u0005[שמא]\u0006 אם יבוא בעל חובו של המוכר ויטרוף מקונה זה את השדה, \u0003טריף\u0004 \u0005[יטרוף]\u0006 הקונה מלקוחות מאוחרים יותר את השדה, ויתן להם את השטר כראיה שטרף מידם את הקרקע, \u0003והדר טריף\u0004 \u0005[ויחזור ויטרוף]\u0006 מלקוחות אחרים על פי השטר האחר!","\u0003הוו קא טרדי ליה\u0004 \u0005[היו מטרידים אותו\u0006 את אביי בבקשתם\u0005],\u0006 \u0003אמר ליה לספריה\u0004 \u0005[לו לסופרו]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003כתוב להו\u0004 \u0005[להם]\u0006 שטר שיהיה \u0003הוא על המחק ועדיו על הנייר,\u0004 שהוא שטר \u0003פסול.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר מניומי לאביי: ודלמא\u0004 \u0005[ושמא]\u0006 יהיה \u0003רישומו\u0004 של שטר זה \u0003ניכר, ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003נמחק או נטשטש, אם רישומו ניכר\u0004 — \u0003כשר,\u0004 ואם כן יישאר החשש שיטרוף פעמיים! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי קאמינא\u0004 \u0005[האם\u0006 התכוונתי \u0005לומר]\u0006 שיכתוב להם \u0003שטרא מעליא\u0004 \u0005[שטר מעולה]?\u0006 \u0003אל\"ף בי\"ת בעלמא קאמינא\u0004 \u0005[בלבד],\u0006 סתם מילים התכוונתי לומר שיכתבו וימחקו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרי שבא\u0004 אדם לפני בית דין \u0003ואמר \"אבד שטר חובי\",\u0004 ואין עדים שאבד לו, \u0003אף על פי שאמרו עדים \"אנו כתבנו וחתמנו ונתננו לו\"\u0004 — \u0003אין\u0004 בית דין \u0003כותבין לו את השטר; במה דברים אמורים\u0004 — \u0003בשטרי הלואה\u0004 שאין כותבים אותם על פי עדות עדים, שמא לא אבד שטרו הראשון, ויוציא אותו ויחזור ויגבה בו. \u0003אבל שטרי מקח וממכר\u0004 — \u0003כותבין\u0004 את השטר מחדש לפי העדים, \u0003חוץ מן האחריות שבו,\u0004 כלומר, בלא האפשרות לגבות מן המוכר או מלקוחות מאוחרים יותר, אם יבוא בעל חובו של המוכר ויטרוף ממנו את הקרקע שקנה. וזאת כדי שלא יוציא את השטר ש\"אבד\" וישתמש בשטר זה לטרוף מלקוחות שלא כדין."],["\u0003רבן שמעון בן גמליאל אומר: אף שטרי מקח וממכר אין כותבין,\u0004 שיש לחשוש שמא החזיר הקונה את השטר למוכר, ולשיטתו נתבטלה בכך המכירה, ואם יהיה לקונה עתה שטר מכר אחר — יחזיר אליו את השדה שלא כדין. \u0003וכן היה רבן שמעון בן גמליאל אומר\u0004 לענין שטר מתנה: \u0003הנותן מתנה לחברו והחזיר לו\u0004 החבר \u0003את השטר\u0004 (שטר המתנה) — \u0003חזרה מתנתו. וחכמים אומרים: מתנתו קיימת,\u0004 למרות שהחזיר את השטר.","ומעתה דנים בפרטי הדינים בברייתא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 מי שטוען שאבד שטר מכר שלו — כותבים לו שטר חדש \u0003חוץ מאחריות שבו,\u0004 שאותה אין כותבים בשטר החדש. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006","\u0003אמר רב ספרא: לפי שאין כותבין שני שטרות\u0004 שיש בהם אחריות \u0003על שדה אחת,\u0004 כי יש חשש בדבר, \u0003דלמא אזיל\u0004 \u0005[שמא ילך]\u0006 \u0003בעל חוב\u0004 של המוכר, שקרקע זו היתה משועבדת לחובו \u0003טריף ליה להאי\u0004 \u0005[ויטרוף מזה],\u0006 את הקרקע שנמכרה לו, \u0003ואזיל האי ומפיק חד וטריף\u0004 \u0005[וילך זה,\u0006 הקונה, \u0005ויוציא\u0006 שטר מכר \u0005אחד\u0006 מהשנים שבידו, \u0005ויטרוף]\u0006 על ידי סעיף האחריות שבו מה \u0003לקוחות\u0004 שקנו אחריו קרקעות מאותו מוכר. \u0003ואמר ליה\u0004 \u0005[ו\u0006אז \u0005יאמר לו]\u0006 \u0003לבעל חוב\u0004 שיעשו יחד קנוניה של הלקוחות: \u0003\"שוף\u0004 \u0005[הנח]\u0006 \u0003לי דאיקום\u0004 \u0005[שאעמוד]\u0006 \u0003בה\u0004 בקרקע שקניתי, \u0003והדר תא טירפן\u0004 \u0005[\u0006\u0005ואחר כך בוא תטרוף אותה ממני]\u0006 פעם שניה \u0003\".\u0004 \u0003ו\u0004אחרי זמן, כשבעל החוב טורף ממנו שוב קרקע זו, \u0003מפיק אחרינא\u0004 \u0005[מוציא\u0006 אותו קונה את השטר \u0005האחר\u0006 שיש בידו על קרקע זו\u0005]\u0006 \u0003והדר אזיל טריף\u0004 \u0005[ושוב הולך וטורף]\u0006 \u0003לקוחות אחריני\u0004 \u0005[אחרים,\u0006 שהרי יש בו אחריות\u0005].\u0006 וכדי למנוע דבר זה, מוציאים את סעיף האחריות מן השטר החדש.","ושואלים: \u0003וכיון דקרעניה לשטרא\u0004 \u0005[שקרענו\u0006 כבר \u0005את שטר]\u0006 ה\u0003מלוה\u0004 פעם אחת, כאשר טרף את השדה בראשונה, \u0003במאי הדר טריף לה\u0004 \u0005[במה יחזור ויטרוף אותה]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003לא קרעניה\u0004 \u0005[קרענו אותו],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב נחמן: כל טירפא\u0004 \u0005[שטר טריפה\u0006 מן קרקעות\u0005]\u0006 שכותב בית הדין, ש\u0003לא כתיב ביה\u0004 \u0005[כתוב בו]\u0006 \u0003\"קרעניה לשטרא\u0004 \u0005[קרענו את שטר\u0006 החוב\u0005]\u0006 של ה\u0003מלוה\u0004 ונתנו לו במקומו שטר טריפה \u0003\"\u0004— \u0003לאו טירפא\u0004 \u0005[לא שטר טריפה]\u0006 \u0003הוא,\u0004 ואינו כשר. \u0003ו\u0004כמו כן, \u0003כל אדרכתא\u0004 \u0005[שטר רדיפה],\u0006 שכתוב בו שרשאי המלוה לרדוף ולקחת מנכסי הלווה בכל מקום שהם ש\u0003לא כתיב ביה\u0004 \u0005[כתוב בו]\u0006 נוסח \u0003\"קרעניה לטירפא\"\u0004 \u0005[קרענו את שטר הטריפה]\u0006 — \u0003לאו אדרכתא\u0004 \u0005[\u0006\u0005לא\u0006 \u0005שטר רדיפה]\u0006 \u0003הוא. ו\u0004כמו כן, \u0003כל\u0004 שטר \u0003שומא\u0004 שכותבים כשמעריכים את שוויים של הנכסים שתפס, ש\u0003לא כתיב ביה\u0004 \u0005[כתוב בו]\u0006 \u0003\"קרעניה לאדרכתא\"\u0004 \u0005[קרענו את שטר הרדיפה]\u0006 — \u0003לאו\u0004 \u0005[לא]\u0006 שטר \u0003שומא\u0004 \u0003היא.\u0004 וכיון שכבר גבה המלוה פעם אחת מנכסי הלקוחות — בוודאי נקרע שטר ההלוואה הראשון, וכיצד הוא יכול לחזור ולטרוף שוב את השדה?","ומשיבים: החשש לקנוניה אינו עם בעל חוב רגיל הבא לטרוף את השדה, שהוא באמת אינו יכול לעשות זאת פעמיים, אלא \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אין אנו חוששים אלא למי שמוציא את השדה מידו בטענת גזל, \u0003דקאתי\u0004 \u0005[שהוא בא]\u0006 \u0003מכח אבהתיה\u0004 \u0005[אבותיו],\u0006 שמוכיח בעדים כי שדה זה באמת שלו מאבותיו. והוא יכול לאחר מספר שנים לחזור ולטרוף, כאשר יביא שוב עדים שהשדה שייך לאבותיו.","על תיאור זה של קנוניה בשני שטרות, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: ולמה ליה\u0004 \u0005[לו]\u0006 לבעל השטרות \u0003למימר ליה\u0004 \u0005[לומר לו]\u0006 \u0003לבעל חוב\u0004 (הבא מכח אבותיו): \u0003\"שוף\u0004 \u0005[הנח]\u0006 \u0003לי בהאי ארעא ואיקום\u0004 \u0005[בקרקע זו ואעמוד]\u0006 \u0003בה\"?\u0004 \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 דרך פשוטה יותר, ש\u0003כיון דנקיט תרי שטרי\u0004 \u0005[ש\u0006הוא \u0005מחזיק שני שטרות]\u0006 — \u0003טריף והדר טריף\u0004 \u0005[טורף\u0006 מלקוח אחד, \u0005וחוזר וטורף\u0006 מלקוח אחר\u0005]\u0006 מיד!","השיב לו: \u0003אם כן\u0004 הוא עושה, \u0003נפישי עליה\u0004 \u0005[מרובים עליו]\u0006 \u0003בעלי דינין,\u0004 יצטרך לבוא לדין עם שני לקוחות שטרף מהם, והוא מפחד שמא יגלו את הרמאות שלו. אבל אם ממתין כמה שנים, יישכח המעשה הראשון, ויוכל לחזור ולטרוף שלא כדין.","ולגופו של דין זה שבברייתא, שכותבים לקונה שטר מכר אחר חוץ מן האחריות שבו, מחשש שמא יחזור ויגבה בשטר הראשון. שואלים: \u0003ולכתוב להאי שטרא מעליא\u0004 \u0005[ושיכתבו לזה שטר מעולה,\u0006 שיש בו אחריות\u0005],\u0006 \u0003ולכתוב תברא\u0004 \u0005[ושיכתוב שובר]\u0006 \u0003למוכר\u0004 שממנו קנה קרקע זו, בנוסח זה: \u0003\"כל שטרי דיפקון\u0004 \u0005[השטרות שייצאו]\u0006 \u0003על ארעא דא\u0004 \u0005[קרקע זו]\u0006 \u0003פסולין, לבר מן דיפוק בזמנא דא\u0004 \u0005[חוץ מ\u0006השטר \u0005שיוצא בתאריך זה]\u0006","\u0003\",\u0004 ואז לא יוכל לטרוף שוב מכוח שטרו הקודם! \u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו אותה חכמים לפני]\u0006 \u0003רב פפא, ואמרי לה קמיה\u0004 \u0005[ויש אומרים\u0006 שאמרו זאת \u0005לפני]\u0006 \u0003רב אשי:\u0004 ממה שאין משתמשים בדרך זו, האם \u0003זאת אומרת\u0004 שככלל \u0003אין כותבין שובר?\u0004 ובמקרה דומה, כשמלוה טוען שאבד שטר חובו — אין מחייבים את הלווה לשלם על סמך שובר שיכתוב לו המלוה, עד שיקבל לידיו את שטר החוב?"],["\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בעלמא\u0004 \u0005[ב\u0006דרך \u0005כלל]\u0006 אצל מלוה \u0003כותבין שובר, והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 שאין כותבים, לפי שעדיין יש חשש לקנוניה, \u0003דדלמא אזיל\u0004 \u0005[שמא ילך]\u0006 \u0003בעל חוב וטריף מיניה\u0004 \u0005[ויטרוף ממנו]\u0006 מן ה\u0003לוקח, ואזיל איהו וטריף\u0004 \u0005[וילך הוא ויטרוף]\u0006 מה \u0003לקוחות\u0004 האחרים שקנו אחריו, ויחזור בעל החוב ויטרוף ממנו, ואז יוציא הוא את השטר השני ויטרוף מלקוחות עם האחריות שבו. ולזה לא יועיל השובר, שהרי ה\u0003שובר גבי\u0004 \u0005[אצל]\u0006 \u0003לקוחות ליכא\u0004 \u0005[אינו\u0006 נמצא\u0005],\u0006 אלא אצל המוכר, והם אינם יודעים מכך.","ושואלים: \u0003סוף סוף, לקוחות לאו אמרי דארעא הדרי\u0004 \u0005[האם לא על בעל הקרקע\u0006 המוכר הם \u0005חוזרים]\u0006 לגבות ממנו, על פי האחריות שנתן להם? ואז יוציא הוא את השובר, ויימצא שהקרקע נלקחה מהם שלא כדין!","ומשיבים: החשש הוא, שמא \u0003אדהכי והכי שמיט ואכיל פירי\u0004 \u0005[בין כך וכך ישמוט ויאכל פירות\u0006 הנמצאים בשדה\u0005].\u0006","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לחשוש \u0003ללוקח שלא באחריות\u0004 שלא יחזור אל המוכר, ולא יתגלה הדבר.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאין סומכים על כתיבת שובר, בגלל הפסד הלקוחות — \u0003שטרי הלואה נמי\u0004 \u0005[גם כן],\u0006 כשטוען המלוה שאבד שטרו, מדוע כותבים שובר? שמא יוציא המלוה את שטרו ויגבה מן הלקוחות, שאין בידם שובר!","ומשיבים: \u0003התם דזוזי מסיק\u0004 \u0005[שם,\u0006 במילוה, \u0005שכסף\u0006 הוא \u0005חייב\u0006 לו\u0005],\u0006 כשבא המלוה לטרוף מן לקוחות \u0003אמרי\u0004 \u0005[אומרים]\u0006 הם: אולי כבר \u0003פייסיה\u0004 \u0005[פייס אותו]\u0006 את \u0003בעל חוב בזוזי\u0004 \u0005[בכסף],\u0006 ולכן אינם ממהרים לתת לו לגבות את הקרקע, אלא מבררים עם הלווה אם כבר שילם את חובו. \u0003הכא דארעא מסיק\u0004 \u0005[כאן,\u0006 במכר, \u0005ש\u0006הקונה הראשון \u0005קרקע\u0006 הוא \u0005נושה\u0006 בו במוכר\u0005],\u0006 ומתוך כך הוא בא לטרוף מהם — אינם אומרים כן\u0005,\u0006 \u0003מידע ידעי דמאן דמסיק ארעא\u0004 \u0005[יודעים\u0006 הם \u0005שמי שנושה קרקע]\u0006 — \u0003בזוזי\u0004 \u0005[בכסף]\u0006 \u0003לא מפייס\u0004 \u0005[יתפייס],\u0006 ולכן יש חשש גדול יותר שיוכל לטרוף מהם בלא שילכו אל המוכר תחילה, ועד שיתברר הדבר — יאכל את פירות שדותיהם.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שאם טען אדם שאבד לו שטר מכר — כותבים שטר מכר \u0003חוץ מן האחריות שבו.\u0004 ומבררים: \u0003היכי כתבינן\u0004 \u0005[כיצד כותבים אנו]\u0006 שטר כזה? \u0003אמר רב נחמן, דכתבי הכי\u0004 \u0005[שכותבים כך]:\u0006 \u0003\"שטרא דנן\u0004 \u0005[שטר זה]\u0006 ש\u0003לא למיגבי ביה\u0004 \u0005[לגבות בו]\u0006 \u0003לא ממשעבדי\u0004 \u0005[ממשועבדים]\u0006 \u0003ולא מבני חרי\u0004 \u0005[חורין],\u0006 \u0003אלא כי היכי דתיקום ארעא בידיה\u0004 \u0005[כדי שתעמוד קרקע\u0006 זו \u0005בידיו]\u0006 של ה\u0003לוקח\"\u0004 כתבנוהו, על מנת שתהיה לו ראיה שקרקע זו היא שלו, ולא יבוא המוכר לערער על כך.","\u0003אמר רפרם, זאת אומרת:\u0004 ש\u0003אחריות\u0004 — \u0003טעות סופר הוא,\u0004 שאם לא נכתבה אחריות נכסים בשטר — אין אנו אומרים שבכוונה הושמטה, אלא אנו מניחים שהיתה זו טעות סופר שלא כתב. וכיצד מוכיחים זאת מדברי רב נחמן — כי \u0003טעמא דכתב ליה הכי\u0004 \u0005[הטעם,\u0006 דווקא כ\u0005שכותב לו כך]\u0006 בצורה מפורשת שאין אחריות בשטר, אז אינו יכול לגבות בו, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא כתב ליה הכי\u0004 \u0005[היה כותב לו כך]\u0006 — \u0003גבי\u0004 \u0005[היה גובה].\u0006","\u0003רב אשי אמר: אחריות\u0004 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003טעות סופר הוא,\u0004 ואם אין אחריות מפורשת בשטר — אין גובה בו אחריות נכסים. \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"חוץ מאחריות שבו\"\u0004 — בפשטות — ש\u0003לא כתיב ביה\u0004 \u0005[כתוב בו]\u0006 סעיף ה\u0003אחריות.\u0004","בענין זה של אחריות, מסופר: \u0003ההיא איתתא דיהבה ליה זוזי לההוא גברא\u0004 \u0003למיזבן\u0004 \u0005[אשה אחת שנתנה כסף לאדם אחד לקנות]\u0006 \u0003לה ארעא\u0004 \u0005[קרקע],\u0006 \u0003אזל זבן\u0004 \u0005[הלך קנה]\u0006 \u0003לה\u0004 קרקע \u0003שלא באחריות; אתיא לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רב נחמן\u0004 להתלונן,","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 הכלל הוא לגבי שליח שיכול המשלח לומר לו: \u0003\"לתקוני שדרתיך\u0004 \u0005[לתקן שלחתיך]\u0006 \u0003ולא לעוותי\"\u0004 \u0005[לקלקל].\u0006 ואתה עשית דבר מקולקל, שלא עשית שליחותך כראוי. וכדי לתקן את הדבר \u0003זיל זבנה מיניה\u0004 \u0005[לך קנה\u0006 אתה את הקרקע \u0005ממנו]\u0006 מן המוכר \u0003שלא באחריות, והדר זבנה ניהלה\u0004 \u0005[ואחר כך תמכרנה לה\u0006 את הקרקע הזו\u0005]\u0006 \u0003באחריות,\u0004 שאם יגבה בעל חובו של המוכר את הקרקע — אתה הוא שתפסיד, שתצטרך לפצות את האשה.","שנינו בברייתא ש\u0003רבן שמעון בן גמליאל אומר: הנותן מתנה לחבירו והחזיר לו\u0004 המקבל \u0003את השטר\u0004 (שטר המתנה) — \u0003חזרה\u0004 בכך \u0003מתנתו, וחכמים אומרים: מתנתו קיימת.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן שמעון בן גמליאל? אמר רב אסי, נעשה כאומר לו\u0004 בשעת הנתינה: \u0003שדה זו נתונה לך כל זמן שהשטר בידך.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבה: אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, אם \u0003נגנב או אבד\u0004 השטר \u0003נמי\u0004 \u0005[גם כן]\u0006 חזרה בכך המתנה!","\u0003אלא אמר רבה:\u0004 רבן שמעון בן גמליאל וחכמים \u0003ב\u0004שאלה האם \u0003אותיות נקנות במסירה קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 כלומר, האם שטרות (והזכויות הכתובות בהם) נקנים מאדם אחד לחבירו על ידי מסירה בלבד, או צריך מעשה אחר כדי להקנותם. ש\u0003רבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003אותיות נקנות במסירה,\u0004 וכיון שהחזיר המקבל את השטר — קנה הנותן יחד עמו גם את החזקה על הנכסים, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין אותיות נקנות במסירה\u0004 וצריכים מעשה נוסף של הקניה. ולכן ההחזקה בשטר אינה מוכיחה דבר. ומבררים את דעתו של רבן שמעון בן גמליאל בענין זה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הבא לידון בשטר ובחזקה\u0004 שבאים ומערערים על בעלותו על קרקע שבידיו, ויש בידו שטר מכר, וגם עדים שהיתה לו חזקה בשדה — הרי זה \u0003נידון בשטר,\u0004 ולפי זה מאמתים את בעלותו. אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר:\u0004 נידון \u0003בחזקה,\u0004 ועל ידי כך מתאמתת בעלותו.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005הם חלוקים]?\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: ב\u0004שאלה אם \u0003אותיות נקנות במסירה קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 כלומר, במקרה בו מסר המוכר לקונה את השטר בו הוא עצמו קנה את השדה,"]]};
